module t65sv #(
  // 0: NMOS only (Mode input ignored). 1: WDC 65C02, 2: Rockwell R65C02,
  // 3: Synertek/GTE 65SC02. When nonzero, Mode != 2'b00 selects the 65C02 at runtime.
  parameter int C02        = 0,
  // 1: always 65C02 (Mode ignored), for tops that are only ever a 65C02; the NMOS table folds away.
  parameter bit C02_FIXED  = 1'b0,
  // 1: 2A03/2A07 behaviour, D flag settable but ADC/SBC/ARR always binary (NMOS path).
  parameter bit NO_DECIMAL = 1'b0,
  // 1: the core is a W65C816S (module t65sv816; Mode, SO_n and BCD_en are ignored). The 6502 logic then drives
  // nothing and synthesis removes it. 0: no 65C816 logic at all.
  parameter bit C816       = 1'b0
) (
  input  logic [1:0]  Mode,
  input  logic        Res_n,
  input  logic        Enable,
  input  logic        Clk,
  input  logic        Rdy,
  /* verilator lint_off UNUSED */
  input  logic        Abort_n,   // accepted for port compatibility; T65 ignores it too
  /* verilator lint_on UNUSED */
  input  logic        IRQ_n,
  input  logic        NMI_n,
  input  logic        SO_n,
  input  logic        BCD_en,  // upstream T65 (C64_MiSTer) extension: 0 = decimal mode disabled (2A03)
  output logic        R_W_n,
  output logic        Sync,
  output logic        EF,
  output logic        MF,
  output logic        XF,
  output logic        ML_n,
  output logic        VP_n,
  output logic        VDA,
  output logic        VPA,
  output logic [23:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO,
  output logic [63:0] Regs,
  output logic [47:0] DEBUG,   // {I, A, X, Y, S, P}: T65's T_t65_dbg record, packed
  output logic        NMI_ack
);

  // ---------------------------------------------------------------- encodings
  localparam logic [2:0] CYC_SYNC = 3'd0;

  localparam logic [4:0] ALU_OR  = 5'd0,  ALU_AND = 5'd1,  ALU_EOR = 5'd2,  ALU_ADC = 5'd3,
                         ALU_EQ1 = 5'd4,  ALU_EQ2 = 5'd5,  ALU_CMP = 5'd6,  ALU_SBC = 5'd7,
                         ALU_ASL = 5'd8,  ALU_ROL = 5'd9,  ALU_LSR = 5'd10, ALU_ROR = 5'd11,
                         ALU_BIT = 5'd12, ALU_DEC = 5'd13, ALU_INC = 5'd14, ALU_ARR = 5'd15,
                         ALU_ANC = 5'd16, ALU_SAX = 5'd17, ALU_XAA = 5'd18,
                         ALU_TSB = 5'd19, ALU_TRB = 5'd20, ALU_BITZ = 5'd21, ALU_RSMB = 5'd22;

  localparam logic [3:0] BA_DI = 4'd0, BA_ABC = 4'd1, BA_X = 4'd2, BA_Y = 4'd3, BA_S = 4'd4,
                         BA_P = 4'd5, BA_DA = 4'd6, BA_DAO = 4'd7, BA_DAX = 4'd8, BA_AAX = 4'd9;

  localparam logic [1:0] AD_PBR = 2'd0, AD_SP = 2'd1, AD_ZPG = 2'd2, AD_BA = 2'd3;

  localparam logic [3:0] WD_DL = 4'd0, WD_ABC = 4'd1, WD_X = 4'd2, WD_Y = 4'd3, WD_S = 4'd4,
                         WD_P = 4'd5, WD_PCL = 4'd6, WD_PCH = 4'd7, WD_AX = 4'd8, WD_AXB = 4'd9,
                         WD_XB = 4'd10, WD_YB = 4'd11, WD_ZERO = 4'd12;

  // ---------------------------------------------------------------- registers
  logic [7:0]  ABC, X, Y;
  logic [7:0]  P, AD, DL;
  logic [7:0]  BAH;
  logic [8:0]  BAL;
  logic [7:0]  PBR, DBR;
  logic [15:0] PC, S;
  logic        EF_i, MF_i, XF_i;
  logic [7:0]  IR;
  logic [2:0]  MCycle;
  logic [1:0]  Mode_r;
  logic        BCD_en_r;
  logic [4:0]  ALU_Op_r;
  logic [3:0]  Write_Data_r;
  logic [1:0]  Set_Addr_To_r;
  logic        RstCycle, IRQCycle, NMICycle;
  logic        SO_n_o, IRQ_n_o, NMI_n_o, NMIAct;
  logic [7:0]  BusA_r, BusB, BusB_r;
  logic        Res_n_i, Res_n_d;
  logic        rdy_mod;
  logic        WRn_i;
  logic        NMI_entered;

  // outputs of the 6502 / 65C02 logic (the ports are driven from these, or from the 65C816 engine; with C816 = 1
  // they have no load)
  /* verilator lint_off UNUSED */
  logic        o_R_W_n, o_Sync, o_EF, o_MF, o_XF, o_ML_n, o_VP_n, o_VDA, o_VPA, o_NMI_ack;
  logic [23:0] o_A;
  logic [7:0]  o_DO;
  logic [63:0] o_Regs;
  logic [47:0] o_DEBUG;
  /* verilator lint_on UNUSED */

  // ---------------------------------------------------------------- combinational
  logic [7:0]  BusA, ALU_Q, P_Out, DO_r, PwithB;
  logic [8:0]  PCAdder;
  logic        Break, really_rdy;

  logic [8:0]  PCRel;
  logic        c02;
  logic        dec_en;

  // micro code outputs (NMOS table n_*, 65C02 table c_*, selected per instruction by c02)
  logic [2:0]  LCycle, n_LCycle, c_LCycle;
  logic [4:0]  ALU_Op, n_ALU_Op, c_ALU_Op;
  logic [3:0]  Set_BusA_To, n_Set_BusA_To, c_Set_BusA_To;
  logic [1:0]  Set_Addr_To, n_Set_Addr_To, c_Set_Addr_To;
  logic [3:0]  Write_Data, n_Write_Data, c_Write_Data;
  logic [1:0]  Jump, n_Jump, c_Jump;
  logic [1:0]  BAAdd, n_BAAdd, c_BAAdd;
  logic [1:0]  BAQuirk, n_BAQuirk;
  logic        BreakAtNA, n_BreakAtNA;
  logic        ADAdd, n_ADAdd, c_ADAdd;
  logic        AddY, n_AddY, c_AddY;
  logic        PCAdd, n_PCAdd, c_PCAdd;
  logic        Inc_S, n_Inc_S, c_Inc_S;
  logic        Dec_S, n_Dec_S, c_Dec_S;
  logic        LDA, n_LDA, c_LDA;
  logic        LDP, n_LDP, c_LDP;
  logic        LDX, n_LDX, c_LDX;
  logic        LDY, n_LDY, c_LDY;
  logic        LDS, n_LDS, c_LDS;
  logic        LDDI, n_LDDI, c_LDDI;
  logic        LDALU, n_LDALU, c_LDALU;
  logic        LDAD, n_LDAD, c_LDAD;
  logic        LDBAL, n_LDBAL, c_LDBAL;
  logic        LDBAH, n_LDBAH, c_LDBAH;
  logic        SaveP, n_SaveP, c_SaveP;
  logic        Write, n_Write, c_Write;
  logic        n_ALUmore;
  // 65C02-only controls
  logic        PCDec, c_PCDec;       // PC <= PC - 1 (JMP (a,x) dummy read of the operand)
  logic        PCHfix, c_PCHfix;     // branch page cross: PCH +/- 1 one cycle after PCL
  logic        BAInc16, c_BAInc16;   // 16-bit pointer increment (JMP (a) has no page-wrap bug)
  logic        Hold, c_Hold;         // WAI / STP

  // ================================================================ NMOS micro code
  logic n_Branch;
  always_comb begin
    case (IR[7:5])
      3'd0: n_Branch = ~P[7];
      3'd1: n_Branch =  P[7];
      3'd2: n_Branch = ~P[6];
      3'd3: n_Branch =  P[6];
      3'd4: n_Branch = ~P[0];
      3'd5: n_Branch =  P[0];
      3'd6: n_Branch = ~P[1];
      default: n_Branch = P[1];
    endcase
  end

  always_comb begin
    n_LCycle      = 3'd1;
    n_Set_BusA_To = BA_ABC;
    n_Set_Addr_To = AD_PBR;
    n_Write_Data  = WD_DL;
    n_Jump        = 2'b00;
    n_BAAdd       = 2'b00;
    n_BAQuirk     = 2'b00;
    n_BreakAtNA   = 1'b0;
    n_ADAdd       = 1'b0;
    n_PCAdd       = 1'b0;
    n_Inc_S       = 1'b0;
    n_Dec_S       = 1'b0;
    n_LDA         = 1'b0;
    n_LDP         = 1'b0;
    n_LDX         = 1'b0;
    n_LDY         = 1'b0;
    n_LDS         = 1'b0;
    n_LDDI        = 1'b0;
    n_LDALU       = 1'b0;
    n_LDAD        = 1'b0;
    n_LDBAL       = 1'b0;
    n_LDBAH       = 1'b0;
    n_SaveP       = 1'b0;
    n_Write       = 1'b0;
    n_AddY        = 1'b0;
    n_ALUmore     = 1'b0;

    case (IR[7:5])
      3'b100: begin
        case (IR[1:0])
          2'b00: begin
            n_Set_BusA_To = BA_Y;
            n_Write_Data  = (IR[4:2] == 3'b111 && !rdy_mod) ? WD_YB : WD_Y;   // SHY $9C
          end
          2'b10: begin
            n_Set_BusA_To = BA_X;
            n_Write_Data  = (IR[4:2] == 3'b111 && !rdy_mod) ? WD_XB : WD_X;   // SHX $9E
          end
          2'b11: begin
            if (IR[4:2] == 3'b110) begin                                      // SHS $9B
              n_Set_BusA_To = BA_AAX;
              n_LDS = 1'b1;
            end else
              n_Set_BusA_To = BA_ABC;
            if ((IR[4:2] == 3'b111 || IR[4:2] == 3'b110 || IR[4:2] == 3'b100) && !rdy_mod)
              n_Write_Data = WD_AXB;
            else
              n_Write_Data = WD_AX;
          end
          default: n_Write_Data = WD_ABC;
        endcase
      end
      3'b101: begin
        n_Set_BusA_To = BA_DI;
        case (IR[1:0])
          2'b00: if (IR[4] != 1'b1 || IR[2] != 1'b0) n_LDY = 1'b1;
          2'b01: n_LDA = 1'b1;
          2'b10: n_LDX = 1'b1;
          default: begin
            n_LDX = 1'b1;
            n_LDA = 1'b1;
            if (IR[4:2] == 3'b110) begin                                      // LAS $BB
              n_Set_BusA_To = BA_S;
              n_LDS = 1'b1;
            end
          end
        endcase
      end
      3'b110: begin
        if (IR[1:0] == 2'b00) begin
          if (!IR[4]) n_LDY = 1'b1;
          n_Set_BusA_To = BA_Y;
        end else
          n_Set_BusA_To = BA_ABC;
      end
      3'b111: begin
        if (IR[1:0] == 2'b00) begin
          if (!IR[4]) n_LDX = 1'b1;
          n_Set_BusA_To = BA_X;
        end else
          n_Set_BusA_To = BA_ABC;
      end
      default: ;
    endcase

    if (IR[7:6] != 2'b10 && IR[1])
      n_Set_BusA_To = (IR == 8'hEB) ? BA_ABC : BA_DI;

    case (IR[4:0])
      5'b00000, 5'b01000, 5'b01010, 5'b11000, 5'b11010: begin
        // implied
        case (IR)
          8'h00: begin                                                        // BRK
            n_LCycle = 3'd6;
            case (MCycle)
              3'd1: begin n_Set_Addr_To = AD_SP; n_Write_Data = WD_PCH; n_Write = 1'b1; end
              3'd2: begin n_Dec_S = 1'b1; n_Set_Addr_To = AD_SP; n_Write_Data = WD_PCL; n_Write = 1'b1; end
              3'd3: begin n_Dec_S = 1'b1; n_Set_Addr_To = AD_SP; n_Write_Data = WD_P; n_Write = 1'b1; end
              3'd4: begin n_Dec_S = 1'b1; n_Set_Addr_To = AD_BA; end
              3'd5: begin n_LDDI = 1'b1; n_Set_Addr_To = AD_BA; end
              3'd6: n_Jump = 2'b10;
              default: ;
            endcase
          end
          8'h20: begin                                                        // JSR
            n_LCycle = 3'd5;
            case (MCycle)
              3'd1: begin n_Jump = 2'b01; n_LDDI = 1'b1; n_Set_Addr_To = AD_SP; end
              3'd2: begin n_Set_Addr_To = AD_SP; n_Write_Data = WD_PCH; n_Write = 1'b1; end
              3'd3: begin n_Dec_S = 1'b1; n_Set_Addr_To = AD_SP; n_Write_Data = WD_PCL; n_Write = 1'b1; end
              3'd4: n_Dec_S = 1'b1;
              3'd5: n_Jump = 2'b10;
              default: ;
            endcase
          end
          8'h40: begin                                                        // RTI
            n_LCycle = 3'd5;
            case (MCycle)
              3'd1: n_Set_Addr_To = AD_SP;
              3'd2: begin n_Inc_S = 1'b1; n_Set_Addr_To = AD_SP; end
              3'd3: begin n_Inc_S = 1'b1; n_Set_Addr_To = AD_SP; n_Set_BusA_To = BA_DI; end
              3'd4: begin n_LDP = 1'b1; n_Inc_S = 1'b1; n_LDDI = 1'b1; n_Set_Addr_To = AD_SP; end
              3'd5: n_Jump = 2'b10;
              default: ;
            endcase
          end
          8'h60: begin                                                        // RTS
            n_LCycle = 3'd5;
            case (MCycle)
              3'd1: n_Set_Addr_To = AD_SP;
              3'd2: begin n_Inc_S = 1'b1; n_Set_Addr_To = AD_SP; end
              3'd3: begin n_Inc_S = 1'b1; n_LDDI = 1'b1; n_Set_Addr_To = AD_SP; end
              3'd4: n_Jump = 2'b10;
              3'd5: n_Jump = 2'b01;
              default: ;
            endcase
          end
          8'h08, 8'h48, 8'h5A, 8'hDA: begin                                   // PHP, PHA; $5A/$DA NOP
            n_LCycle = IR[1] ? 3'd1 : 3'd2;
            case (MCycle)
              3'd1: if (!IR[1]) begin
                n_Write = 1'b1;
                n_Write_Data = IR[6] ? WD_ABC : WD_P;
                n_Set_Addr_To = AD_SP;
              end
              3'd2: n_Dec_S = 1'b1;
              default: ;
            endcase
          end
          8'h28, 8'h68, 8'h7A, 8'hFA: begin                                   // PLP, PLA; $7A/$FA NOP
            n_LCycle = IR[1] ? 3'd1 : 3'd3;
            if (IR[7:4] == 4'b0010) n_LDP = 1'b1;
            if (IR[7:4] == 4'b0110) n_LDA = 1'b1;
            case (MCycle)
              3'd0: if (!IR[1]) n_SaveP = 1'b1;
              3'd1: if (!IR[1]) begin n_Set_Addr_To = AD_SP; n_LDP = 1'b0; end
              3'd2: begin n_Inc_S = 1'b1; n_Set_Addr_To = AD_SP; n_LDP = 1'b0; end
              3'd3: n_Set_BusA_To = BA_DI;
              default: ;
            endcase
          end
          8'hA0, 8'hC0, 8'hE0: if (MCycle == 3'd1) n_Jump = 2'b01;             // n_LDY/CPY/CPX #
          8'h88: begin n_LDY = 1'b1; if (MCycle == 3'd1) n_Set_BusA_To = BA_Y; end // DEY
          8'hCA: begin n_LDX = 1'b1; if (MCycle == 3'd1) n_Set_BusA_To = BA_X; end // DEX
          8'h1A, 8'h3A: begin                                                 // NOP (65C02 INC/DEC A)
            n_LCycle = 3'd1;
            if (MCycle == 3'd1) n_Set_BusA_To = BA_S;
          end
          8'h0A, 8'h2A, 8'h4A, 8'h6A: begin n_LDA = 1'b1; n_Set_BusA_To = BA_ABC; end
          8'h8A, 8'h98: n_LDA = 1'b1;                                           // TXA, TYA
          8'hAA, 8'hA8: if (MCycle == 3'd1) n_Set_BusA_To = BA_ABC;             // TAX, TAY
          8'h9A: n_LDS = 1'b1;                                                  // TXS
          8'hBA: begin n_LDX = 1'b1; if (MCycle == 3'd1) n_Set_BusA_To = BA_S; end // TSX
          8'h80: if (MCycle == 3'd1) n_Jump = 2'b01;                            // NOP #
          default: ;
        endcase
      end

      5'b00001, 5'b00011: begin
        // (zp,X)
        n_LCycle = 3'd5;
        if (IR[7:6] != 2'b10) begin
          n_LDA = 1'b1;
          if (IR[1]) n_LCycle = 3'd7;
        end
        case (MCycle)
          3'd1: begin n_Jump = 2'b01; n_LDAD = 1'b1; n_Set_Addr_To = AD_ZPG; end
          3'd2: begin n_ADAdd = 1'b1; n_Set_Addr_To = AD_ZPG; end
          3'd3: begin n_BAAdd = 2'b01; n_LDBAL = 1'b1; n_Set_Addr_To = AD_ZPG; end
          3'd4: begin
            n_LDBAH = 1'b1;
            if (IR[7:5] == 3'b100) n_Write = 1'b1;
            n_Set_Addr_To = AD_BA;
          end
          3'd5: if (IR[1] && IR[7:6] != 2'b10) begin
            n_Set_Addr_To = AD_BA; n_Write = 1'b1; n_LDDI = 1'b1;
          end
          3'd6: begin n_Write = 1'b1; n_LDALU = 1'b1; n_SaveP = 1'b1; n_Set_Addr_To = AD_BA; end
          3'd7: begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
          default: ;
        endcase
      end

      5'b01001: begin
        // immediate
        if (IR[7:5] != 3'b100) n_LDA = 1'b1;
        if (MCycle == 3'd1) n_Jump = 2'b01;
      end

      5'b01011: begin
        // undocumented immediates
        case (IR[7:5])
          3'b000, 3'b001, 3'b010, 3'b011: begin n_Set_BusA_To = BA_DA; n_LDA = 1'b1; end
          3'b100: begin n_Set_BusA_To = BA_DAX; n_LDA = 1'b1; end
          3'b110: begin n_Set_BusA_To = BA_AAX; n_LDX = 1'b1; end
          3'b101: begin n_Set_BusA_To = BA_DAO; n_LDA = 1'b1; end
          default: n_LDA = 1'b1;
        endcase
        if (MCycle == 3'd1) n_Jump = 2'b01;
      end

      5'b00010, 5'b10010: begin
        // immediate, NOP #, JAM
        if (MCycle == 3'd1) begin
          if (IR == 8'hA2) begin
            n_Jump = 2'b01;
            n_LDX  = 1'b1;
          end else if (IR[7:4] == 4'b1000 || IR[7:4] == 4'b1100 || IR[7:4] == 4'b1110)
            n_Jump = 2'b01;
        end
      end

      5'b00100: begin
        // zero page (BIT/STY/n_LDY/CPY/CPX/NOP)
        n_LCycle = 3'd2;
        case (MCycle)
          3'd0: if (IR[7:5] == 3'b001) n_SaveP = 1'b1;
          3'd1: begin
            n_Jump = 2'b01; n_LDAD = 1'b1;
            if (IR[7:5] == 3'b100) n_Write = 1'b1;
            n_Set_Addr_To = AD_ZPG;
          end
          default: ;
        endcase
      end

      5'b00101, 5'b00110, 5'b00111: begin
        // zero page
        if (IR[7:6] != 2'b10 && IR[1]) begin
          // read-modify-write
          n_LCycle = 3'd4;
          if (IR[0]) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDAD = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd2: begin n_LDDI = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd3: begin n_LDALU = 1'b1; n_SaveP = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd4: if (IR[0]) begin n_Set_BusA_To = BA_ABC; n_ALUmore = 1'b1; n_LDDI = 1'b1; end
            default: ;
          endcase
        end else begin
          n_LCycle = 3'd2;
          if (IR[7:6] != 2'b10) n_LDA = 1'b1;
          if (MCycle == 3'd1) begin
            n_Jump = 2'b01; n_LDAD = 1'b1;
            if (IR[7:5] == 3'b100) n_Write = 1'b1;
            n_Set_Addr_To = AD_ZPG;
          end
        end
      end

      5'b01100: begin
        // absolute (BIT/JMP/STY/n_LDY/CPY/CPX/NOP)
        if (IR[7:6] == 2'b01) begin
          if (!IR[5]) begin                                                   // JMP abs
            n_LCycle = 3'd2;
            case (MCycle)
              3'd1: begin n_Jump = 2'b01; n_LDDI = 1'b1; end
              3'd2: n_Jump = 2'b10;
              default: ;
            endcase
          end else begin                                                      // JMP (abs)
            n_LCycle = 3'd4;
            case (MCycle)
              3'd1: begin n_Jump = 2'b01; n_LDDI = 1'b1; n_LDBAL = 1'b1; end
              3'd2: begin n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA; end
              3'd3: begin n_LDDI = 1'b1; n_Set_Addr_To = AD_BA; n_BAAdd = 2'b01; end
              3'd4: n_Jump = 2'b10;
              default: ;
            endcase
          end
        end else begin
          n_LCycle = 3'd3;
          case (MCycle)
            3'd0: if (IR[7:5] == 3'b001) n_SaveP = 1'b1;
            3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
            3'd2: begin
              n_Jump = 2'b01; n_LDBAH = 1'b1;
              if (IR[7:5] == 3'b100) n_Write = 1'b1;
              n_Set_Addr_To = AD_BA;
            end
            default: ;
          endcase
        end
      end

      5'b01101, 5'b01110, 5'b01111: begin
        // absolute
        if (IR[7:6] != 2'b10 && IR[1]) begin
          // read-modify-write
          n_LCycle = 3'd5;
          if (IR[0]) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
            3'd2: begin n_Jump = 2'b01; n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA; end
            3'd3: begin n_LDDI = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_BA; end
            3'd4: begin n_Write = 1'b1; n_LDALU = 1'b1; n_SaveP = 1'b1; n_Set_Addr_To = AD_BA; end
            3'd5: if (IR[0]) begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
            default: ;
          endcase
        end else begin
          n_LCycle = 3'd3;
          if (IR[7:6] != 2'b10) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
            3'd2: begin
              n_Jump = 2'b01; n_LDBAH = 1'b1;
              if (IR[7:5] == 3'b100) n_Write = 1'b1;
              n_Set_Addr_To = AD_BA;
            end
            default: ;
          endcase
        end
      end

      5'b10000: begin
        // relative: T2 ends a not-taken branch, Break ends a taken one without page cross
        n_LCycle = n_Branch ? 3'd3 : 3'd1;
        case (MCycle)
          3'd1: begin n_Jump = 2'b01; n_LDDI = 1'b1; end
          3'd2: begin n_Jump = 2'b11; n_PCAdd = 1'b1; end
          default: ;
        endcase
      end

      5'b10001, 5'b10011: begin
        // (zp),Y
        n_LCycle = 3'd5;
        if (IR[7:6] != 2'b10) begin
          n_LDA = 1'b1;
          if (IR[1]) n_LCycle = 3'd7;
        end
        case (MCycle)
          3'd1: begin n_Jump = 2'b01; n_LDAD = 1'b1; n_Set_Addr_To = AD_ZPG; end
          3'd2: begin n_LDBAL = 1'b1; n_BAAdd = 2'b01; n_Set_Addr_To = AD_ZPG; end
          3'd3: begin n_Set_BusA_To = BA_Y; n_BAAdd = 2'b10; n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA; end
          3'd4: begin
            n_BAAdd = 2'b11;
            if (IR[7:5] == 3'b100) begin
              n_Write = 1'b1;
              if (IR[3:0] == 4'h3) n_BAQuirk = 2'b10;                           // SHA (zp),Y: copy
            end else if (!IR[1] || IR == 8'hB3)
              n_BreakAtNA = 1'b1;
            n_Set_Addr_To = AD_BA;
          end
          3'd5: if (IR[1] && IR[7:6] != 2'b10) begin
            n_Set_Addr_To = AD_BA; n_LDDI = 1'b1; n_Write = 1'b1;
          end
          3'd6: begin n_LDALU = 1'b1; n_SaveP = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_BA; end
          3'd7: begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
          default: ;
        endcase
      end

      5'b10100, 5'b10101, 5'b10110, 5'b10111: begin
        // zp,X / zp,Y
        if (IR[7:6] != 2'b10 && IR[1]) begin
          // read-modify-write
          if (IR[0]) n_LDA = 1'b1;
          n_LCycle = 3'd5;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDAD = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd2: begin n_ADAdd = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd3: begin n_LDDI = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd4: begin
              n_LDALU = 1'b1; n_SaveP = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_ZPG;
              if (IR[0]) n_LDDI = 1'b1;
            end
            3'd5: if (IR[0]) begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
            default: ;
          endcase
        end else begin
          n_LCycle = 3'd3;
          if (IR[7:6] != 2'b10 && IR[0]) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDAD = 1'b1; n_Set_Addr_To = AD_ZPG; end
            3'd2: begin
              n_ADAdd = 1'b1;
              if (IR[3:1] == 3'b011) n_AddY = 1'b1;
              if (IR[7:5] == 3'b100) n_Write = 1'b1;
              n_Set_Addr_To = AD_ZPG;
            end
            default: ;
          endcase
        end
      end

      5'b11001, 5'b11011: begin
        // abs,Y
        n_LCycle = 3'd4;
        if (IR[7:6] != 2'b10) begin
          n_LDA = 1'b1;
          if (IR[1]) n_LCycle = 3'd6;
        end
        case (MCycle)
          3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
          3'd2: begin
            n_Jump = 2'b01; n_Set_BusA_To = BA_Y; n_BAAdd = 2'b10; n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA;
          end
          3'd3: begin
            n_BAAdd = 2'b11;
            if (IR[7:5] == 3'b100) begin
              n_Write = 1'b1;
              if (IR[3:0] == 4'hB) n_BAQuirk = 2'b01;                           // SHS: and
            end else if (!IR[1] || IR == 8'hBB)
              n_BreakAtNA = 1'b1;
            n_Set_Addr_To = AD_BA;
          end
          3'd4: if (IR[1] && IR[7:6] != 2'b10) begin
            n_Set_Addr_To = AD_BA; n_LDDI = 1'b1; n_Write = 1'b1;
          end
          3'd5: begin n_Write = 1'b1; n_LDALU = 1'b1; n_Set_Addr_To = AD_BA; n_SaveP = 1'b1; end
          3'd6: begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
          default: ;
        endcase
      end

      5'b11100, 5'b11101, 5'b11110, 5'b11111: begin
        // abs,X / abs,Y ($BE/$BF/$9E/$9F)
        if (IR[7:6] != 2'b10 && IR[1]) begin
          // read-modify-write
          n_LCycle = 3'd6;
          if (IR[0]) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
            3'd2: begin
              n_Jump = 2'b01; n_Set_BusA_To = BA_X; n_BAAdd = 2'b10; n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA;
            end
            3'd3: begin n_BAAdd = 2'b11; n_Set_Addr_To = AD_BA; end
            3'd4: begin n_LDDI = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_BA; end
            3'd5: begin n_LDALU = 1'b1; n_SaveP = 1'b1; n_Write = 1'b1; n_Set_Addr_To = AD_BA; end
            3'd6: if (IR[0]) begin n_ALUmore = 1'b1; n_Set_BusA_To = BA_ABC; end
            default: ;
          endcase
        end else begin
          n_LCycle = 3'd4;
          if (IR[7:6] != 2'b10 && IR[1:0] != 2'b00) n_LDA = 1'b1;
          case (MCycle)
            3'd1: begin n_Jump = 2'b01; n_LDBAL = 1'b1; end
            3'd2: begin
              n_Jump = 2'b01;
              n_Set_BusA_To = (IR[7:6] == 2'b10 && IR[4:1] == 4'b1111) ? BA_Y : BA_X;
              n_BAAdd = 2'b10; n_LDBAH = 1'b1; n_Set_Addr_To = AD_BA;
            end
            3'd3: begin
              n_BAAdd = 2'b11;
              if (IR[7:5] == 3'b100) begin
                n_Write = 1'b1;
                case (IR[1:0])
                  2'b00, 2'b10: n_BAQuirk = 2'b01;                              // SHY/SHX: and
                  2'b11:        n_BAQuirk = 2'b10;                              // SHA: copy
                  default: ;
                endcase
              end else
                n_BreakAtNA = 1'b1;
              n_Set_Addr_To = AD_BA;
            end
            default: ;
          endcase
        end
      end
      default: ;
    endcase
  end

  // ALU operation decode
  always_comb begin
    case (IR[1:0])
      2'b00: begin
        case (IR[4:2])
          3'b000, 3'b001, 3'b011: begin
            case (IR[7:5])
              3'b110, 3'b111: n_ALU_Op = ALU_CMP;
              3'b101:         n_ALU_Op = ALU_EQ2;
              3'b001:         n_ALU_Op = ALU_BIT;
              default:        n_ALU_Op = ALU_EQ1;
            endcase
          end
          3'b010: begin
            case (IR[7:5])
              3'b111, 3'b110: n_ALU_Op = ALU_INC;
              3'b100:         n_ALU_Op = ALU_DEC;
              default:        n_ALU_Op = ALU_EQ2;
            endcase
          end
          3'b110: n_ALU_Op = (IR[7:5] == 3'b100) ? ALU_EQ2 : ALU_EQ1;
          default: n_ALU_Op = (IR[7:5] == 3'b101) ? ALU_EQ2 : ALU_EQ1;
        endcase
      end
      2'b01: begin
        case (IR[7:5])
          3'd0: n_ALU_Op = ALU_OR;
          3'd1: n_ALU_Op = ALU_AND;
          3'd2: n_ALU_Op = ALU_EOR;
          3'd3: n_ALU_Op = ALU_ADC;
          3'd4: n_ALU_Op = ALU_EQ1;
          3'd5: n_ALU_Op = ALU_EQ2;
          3'd6: n_ALU_Op = ALU_CMP;
          default: n_ALU_Op = ALU_SBC;
        endcase
      end
      2'b10: begin
        case (IR[7:5])
          3'd0: n_ALU_Op = ALU_ASL;
          3'd1: n_ALU_Op = ALU_ROL;
          3'd2: n_ALU_Op = ALU_LSR;
          3'd3: n_ALU_Op = ALU_ROR;
          3'd4: n_ALU_Op = (IR[4:2] == 3'b010) ? ALU_EQ2 : ALU_EQ1;
          3'd5: n_ALU_Op = ALU_EQ2;
          3'd6: n_ALU_Op = ALU_DEC;
          default: n_ALU_Op = ALU_INC;
        endcase
      end
      default: begin
        if (IR[7:5] == 3'd5)
          n_ALU_Op = (IR == 8'hBB) ? ALU_AND : ALU_EQ2;
        else if (IR == 8'h6B) n_ALU_Op = ALU_ARR;
        else if (IR == 8'h8B) n_ALU_Op = ALU_XAA;
        else if (IR == 8'h0B || IR == 8'h2B) n_ALU_Op = ALU_ANC;
        else if (IR == 8'hEB) n_ALU_Op = ALU_SBC;
        else if (n_ALUmore) begin
          case (IR[7:5])
            3'd0: n_ALU_Op = ALU_OR;
            3'd1: n_ALU_Op = ALU_AND;
            3'd2: n_ALU_Op = ALU_EOR;
            3'd3: n_ALU_Op = ALU_ADC;
            3'd4: n_ALU_Op = ALU_EQ1;
            3'd6: n_ALU_Op = ALU_CMP;
            default: n_ALU_Op = ALU_SBC;
          endcase
        end else begin
          case (IR[7:5])
            3'd0: n_ALU_Op = ALU_ASL;
            3'd1: n_ALU_Op = ALU_ROL;
            3'd2: n_ALU_Op = ALU_LSR;
            3'd3: n_ALU_Op = ALU_ROR;
            3'd4: n_ALU_Op = ALU_BIT;
            3'd6: n_ALU_Op = (IR[4:2] == 3'b010) ? ALU_SAX : ALU_DEC;          // $CB SBX
            default: n_ALU_Op = ALU_INC;
          endcase
        end
      end
    endcase
  end


  // ================================================================ 65C02 micro code
  // Bus cycles follow SingleStepTests wdc65c02 / rockwell65c02 / synertek65c02.
  localparam bit C02_BITOPS = (C02 == 1) || (C02 == 2);   // RMB/SMB/BBR/BBS
  localparam bit C02_WAISTP = (C02 == 1);

  localparam logic [3:0] AM_IMP = 4'd0, AM_IMM = 4'd1, AM_ZP = 4'd2, AM_ZPX = 4'd3, AM_ABS = 4'd4,
                         AM_ABX = 4'd5, AM_IZX = 4'd6, AM_IZY = 4'd7, AM_IZP = 4'd8, AM_RZP = 4'd9,
                         AM_RZPX = 4'd10, AM_RABS = 4'd11, AM_RABX = 4'd12, AM_SPC = 4'd13;

  always_comb begin : c02_mcode
    logic       col01, xtra, wr, idxy, alw, savep0, cy, d3, bbt, cyx, cyy;
    logic [3:0] am;
    logic [7:0] bal8;

    c_LCycle      = 3'd1;
    c_Set_BusA_To = BA_ABC;
    c_Set_Addr_To = AD_PBR;
    c_Write_Data  = WD_DL;
    c_Jump        = 2'b00;
    c_BAAdd       = 2'b00;
    c_ADAdd       = 1'b0;
    c_AddY        = 1'b0;
    c_PCAdd       = 1'b0;
    c_Inc_S       = 1'b0;
    c_Dec_S       = 1'b0;
    c_LDA         = 1'b0;
    c_LDP         = 1'b0;
    c_LDX         = 1'b0;
    c_LDY         = 1'b0;
    c_LDS         = 1'b0;
    c_LDDI        = 1'b0;
    c_LDALU       = 1'b0;
    c_LDAD        = 1'b0;
    c_LDBAL       = 1'b0;
    c_LDBAH       = 1'b0;
    c_SaveP       = 1'b0;
    c_Write       = 1'b0;
    c_PCDec       = 1'b0;
    c_PCHfix      = 1'b0;
    c_BAInc16     = 1'b0;
    c_Hold        = 1'b0;
    c_ALU_Op      = ALU_EQ1;

    col01  = (IR[1:0] == 2'b01) || (IR[4:0] == 5'b10010);    // ORA..SBC, incl. (zp)
    xtra   = col01 && IR[6:5] == 2'b11 && dec_en;            // decimal ADC/SBC: one more read of the EA
    cyx    = BAL[7:0] > ~X;                                  // carry out of BAL + X (BA add this cycle)
    cyy    = BAL[7:0] > ~Y;
    bal8   = BAL[7:0];
    bbt    = (bal8[IR[6:4]] == IR[7]);                       // BBR/BBS: operand byte held in BAL
    wr     = 1'b0;
    idxy   = 1'b0;
    alw    = 1'b0;
    savep0 = 1'b0;
    am     = AM_IMP;

    if (C02 != 0) begin
      // ---- register / bus selection
      if (col01) begin
        case (IR[7:5])
          3'b100: c_Write_Data = WD_ABC;
          3'b101: begin c_Set_BusA_To = BA_DI; c_LDA = 1'b1; end
          default: c_LDA = 1'b1;     // CMP reloads A unchanged: that is how T65 commits its flags
        endcase
      end else begin
        case (IR[1:0])
          2'b00: begin
            case (IR[7:5])
              3'b100: begin c_Set_BusA_To = BA_Y; c_Write_Data = WD_Y; end
              3'b101: begin c_Set_BusA_To = BA_DI; if (!IR[4] || IR[2]) c_LDY = 1'b1; end
              3'b110: begin c_Set_BusA_To = BA_Y; if (!IR[4]) c_LDY = 1'b1; end
              3'b111: begin c_Set_BusA_To = BA_X; if (!IR[4]) c_LDX = 1'b1; end
              default: ;
            endcase
          end
          2'b10: begin
            case (IR[7:5])
              3'b100: begin c_Set_BusA_To = BA_X; c_Write_Data = WD_X; end
              3'b101: begin c_Set_BusA_To = BA_DI; c_LDX = 1'b1; end
              default: c_Set_BusA_To = BA_DI;
            endcase
          end
          default: c_Set_BusA_To = BA_DI;
        endcase
      end

      // ---- ALU operation
      if (col01) begin
        case (IR[7:5])
          3'd0: c_ALU_Op = ALU_OR;
          3'd1: c_ALU_Op = ALU_AND;
          3'd2: c_ALU_Op = ALU_EOR;
          3'd3: c_ALU_Op = ALU_ADC;
          3'd4: c_ALU_Op = (IR == 8'h89) ? ALU_BITZ : ALU_EQ1;
          3'd5: c_ALU_Op = ALU_EQ2;
          3'd6: c_ALU_Op = ALU_CMP;
          default: c_ALU_Op = ALU_SBC;
        endcase
      end else begin
        case (IR)
          8'h04, 8'h0C: c_ALU_Op = ALU_TSB;
          8'h14, 8'h1C: c_ALU_Op = ALU_TRB;
          8'h34, 8'h3C: c_ALU_Op = ALU_BIT;
          8'h1A:        c_ALU_Op = ALU_INC;
          8'h3A:        c_ALU_Op = ALU_DEC;
          8'h7A, 8'hFA: c_ALU_Op = ALU_EQ2;
          default:      c_ALU_Op = (IR[1:0] == 2'b11) ? ALU_RSMB : n_ALU_Op;
        endcase
      end

      // ---- addressing template
      case (IR[4:0])
        5'b00000: am = (IR[7] && IR[6:5] != 2'b00) ? AM_IMM : AM_SPC;     // LDY/CPY/CPX # vs BRK/JSR/RTI/RTS/BRA
        5'b01000: am = IR[7] ? AM_IMP : AM_SPC;                            // PHP/PLP/PHA/PLA
        5'b11010: am = IR[6] ? AM_SPC : AM_IMP;                           // PHY/PLY/PHX/PLX
        5'b10000, 5'b01111, 5'b11111: am = AM_SPC;
        5'b00001: begin am = AM_IZX; wr = (IR[7:5] == 3'b100); end
        5'b00010: am = AM_IMM;
        5'b10010: begin am = AM_IZP; wr = (IR[7:5] == 3'b100); end
        5'b00100: begin am = (IR[7:5] == 3'b000) ? AM_RZP : AM_ZP; wr = (IR[7:5] == 3'b011 || IR[7:5] == 3'b100); end
        5'b00101: begin am = AM_ZP; wr = (IR[7:5] == 3'b100); end
        5'b00110: begin am = (IR[7:6] == 2'b10) ? AM_ZP : AM_RZP; wr = (IR[7:5] == 3'b100); end
        5'b00111: am = AM_RZP;                                             // RMB/SMB
        5'b01001: am = AM_IMM;
        5'b01100: begin
          am = (IR[7:5] == 3'b000) ? AM_RABS : (IR[7:6] == 2'b01) ? AM_SPC : AM_ABS;
          wr = (IR[7:5] == 3'b100);
        end
        5'b01101: begin am = AM_ABS; wr = (IR[7:5] == 3'b100); end
        5'b01110: begin am = (IR[7:6] == 2'b10) ? AM_ABS : AM_RABS; wr = (IR[7:5] == 3'b100); end
        5'b10001: begin am = AM_IZY; wr = (IR[7:5] == 3'b100); end
        5'b10100: begin am = (IR[7:5] == 3'b000) ? AM_RZP : AM_ZPX; wr = (IR[7:5] == 3'b011 || IR[7:5] == 3'b100); end
        5'b10101: begin am = AM_ZPX; wr = (IR[7:5] == 3'b100); end
        5'b10110: begin am = (IR[7:6] == 2'b10) ? AM_ZPX : AM_RZPX; wr = (IR[7:5] == 3'b100); idxy = (IR[7:6] == 2'b10); end
        5'b10111: am = AM_RZP;
        5'b11001: begin am = AM_ABX; idxy = 1'b1; wr = (IR[7:5] == 3'b100); end
        5'b11100: begin
          case (IR[7:5])
            3'b000: am = AM_RABS;                                  // TRB abs
            3'b001, 3'b101: am = AM_ABX;                           // BIT abs,X / LDY abs,X
            3'b100: begin am = AM_ABS; wr = 1'b1; end              // STZ abs
            default: am = AM_SPC;                                  // JMP (a,x), NOPs
          endcase
        end
        5'b11101: begin am = AM_ABX; wr = (IR[7:5] == 3'b100); end
        5'b11110: begin
          case (IR[7:5])
            3'b100: begin am = AM_ABX; wr = 1'b1; end              // STZ abs,X
            3'b101: begin am = AM_ABX; idxy = 1'b1; end            // LDX abs,Y
            default: begin am = AM_RABX; alw = IR[7]; end          // INC/DEC abs,X always 7 cycles
          endcase
        end
        5'b01011, 5'b11011: am = AM_SPC;                                   // WAI / STP (others are 1-cycle NOPs)
        default: am = AM_IMP;
      endcase
      if (IR == 8'h89 || IR[7:5] == 3'b001 && (IR[4:0] == 5'b00100 || IR[4:0] == 5'b01100 ||
                                              IR[4:0] == 5'b10100 || IR[4:0] == 5'b11100))
        savep0 = 1'b1;                                             // BIT: flags at the next fetch
      if (IR == 8'h64 || IR == 8'h74 || IR == 8'h9C || IR == 8'h9E) c_Write_Data = WD_ZERO;
      if (MCycle == CYC_SYNC && savep0) c_SaveP = 1'b1;

      cy = idxy ? cyy : cyx;
      d3 = alw | BAL[8];

      case (am)
        AM_IMM: begin
          // decimal: PC stays on the operand, the extra cycle re-reads it (SST shows a constant dummy address)
          c_LCycle = xtra ? 3'd2 : 3'd1;
          if (MCycle == 3'd1 && !xtra || MCycle == 3'd2) c_Jump = 2'b01;
        end
        AM_ZP: begin
          c_LCycle = xtra ? 3'd3 : 3'd2;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Write = wr; c_Set_Addr_To = AD_ZPG; end
            3'd2: if (xtra) c_Set_Addr_To = AD_ZPG;
            default: ;
          endcase
        end
        AM_ZPX: begin
          c_LCycle = xtra ? 3'd4 : 3'd3;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_ADAdd = 1'b1; c_AddY = idxy; c_Write = wr; c_Set_Addr_To = AD_ZPG; end
            3'd3: if (xtra) c_Set_Addr_To = AD_ZPG;
            default: ;
          endcase
        end
        AM_ABS: begin
          c_LCycle = xtra ? 3'd4 : 3'd3;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
            3'd2: begin c_Jump = 2'b01; c_LDBAH = 1'b1; c_Write = wr; c_Set_Addr_To = AD_BA; end
            3'd3: if (xtra) c_Set_Addr_To = AD_BA;
            default: ;
          endcase
        end
        AM_ABX: begin
          // page cross (or any store): dummy read of the last operand byte, PC is held there
          c_LCycle = wr ? 3'd4 : (3'd3 + {2'b00, BAL[8]} + {2'b00, xtra});
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
            3'd2: begin
              c_LDBAH = 1'b1; c_Set_BusA_To = idxy ? BA_Y : BA_X; c_BAAdd = 2'b10;
              c_Set_Addr_To = (wr || cy) ? AD_PBR : AD_BA;
            end
            3'd3: begin
              c_Jump = 2'b01;
              if (wr || BAL[8]) begin c_BAAdd = 2'b11; c_Write = wr; c_Set_Addr_To = AD_BA; end
              else if (xtra) c_Set_Addr_To = AD_BA;
            end
            3'd4: if (xtra && BAL[8]) c_Set_Addr_To = AD_BA;
            default: ;
          endcase
        end
        AM_IZX: begin
          c_LCycle = xtra ? 3'd6 : 3'd5;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_ADAdd = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd3: begin c_BAAdd = 2'b01; c_LDBAL = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd4: begin c_LDBAH = 1'b1; c_Write = wr; c_Set_Addr_To = AD_BA; end
            3'd5: if (xtra) c_Set_Addr_To = AD_BA;
            default: ;
          endcase
        end
        AM_IZP: begin
          c_LCycle = xtra ? 3'd5 : 3'd4;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_LDBAL = 1'b1; c_BAAdd = 2'b01; c_Set_Addr_To = AD_ZPG; end
            3'd3: begin c_LDBAH = 1'b1; c_Write = wr; c_Set_Addr_To = AD_BA; end
            3'd4: if (xtra) c_Set_Addr_To = AD_BA;
            default: ;
          endcase
        end
        AM_IZY: begin
          // PC stays on the operand byte until the dummy read of it
          c_LCycle = wr ? 3'd5 : (3'd4 + {2'b00, BAL[8]} + {2'b00, xtra});
          case (MCycle)
            3'd1: begin c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_LDBAL = 1'b1; c_BAAdd = 2'b01; c_Set_Addr_To = AD_ZPG; end
            3'd3: begin
              c_LDBAH = 1'b1; c_Set_BusA_To = BA_Y; c_BAAdd = 2'b10;
              c_Set_Addr_To = (wr || cyy) ? AD_PBR : AD_BA;
            end
            3'd4: begin
              c_Jump = 2'b01;
              if (wr || BAL[8]) begin c_BAAdd = 2'b11; c_Write = wr; c_Set_Addr_To = AD_BA; end
              else if (xtra) c_Set_Addr_To = AD_BA;
            end
            3'd5: if (xtra && BAL[8]) c_Set_Addr_To = AD_BA;
            default: ;
          endcase
        end
        AM_RZP: begin
          c_LCycle = 3'd4;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_LDDI = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd3: begin c_LDALU = 1'b1; c_SaveP = 1'b1; c_Write = 1'b1; c_Set_Addr_To = AD_ZPG; end
            default: ;
          endcase
        end
        AM_RZPX: begin
          c_LCycle = 3'd5;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd2: begin c_ADAdd = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd3: begin c_LDDI = 1'b1; c_Set_Addr_To = AD_ZPG; end
            3'd4: begin c_LDALU = 1'b1; c_SaveP = 1'b1; c_Write = 1'b1; c_Set_Addr_To = AD_ZPG; end
            default: ;
          endcase
        end
        AM_RABS: begin
          c_LCycle = 3'd5;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
            3'd2: begin c_Jump = 2'b01; c_LDBAH = 1'b1; c_Set_Addr_To = AD_BA; end
            3'd3: begin c_LDDI = 1'b1; c_Set_Addr_To = AD_BA; end
            3'd4: begin c_LDALU = 1'b1; c_SaveP = 1'b1; c_Write = 1'b1; c_Set_Addr_To = AD_BA; end
            default: ;
          endcase
        end
        AM_RABX: begin
          c_LCycle = d3 ? 3'd6 : 3'd5;
          case (MCycle)
            3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
            3'd2: begin
              c_LDBAH = 1'b1; c_Set_BusA_To = BA_X; c_BAAdd = 2'b10;
              c_Set_Addr_To = (alw || cyx) ? AD_PBR : AD_BA;
            end
            3'd3: begin
              c_Jump = 2'b01; c_Set_Addr_To = AD_BA;
              if (d3) c_BAAdd = 2'b11; else c_LDDI = 1'b1;
            end
            3'd4: begin
              c_Set_Addr_To = AD_BA;
              if (d3) c_LDDI = 1'b1; else begin c_LDALU = 1'b1; c_SaveP = 1'b1; c_Write = 1'b1; end
            end
            3'd5: if (d3) begin c_LDALU = 1'b1; c_SaveP = 1'b1; c_Write = 1'b1; c_Set_Addr_To = AD_BA; end
            default: ;
          endcase
        end
        AM_SPC: begin
          case (IR)
            8'h00: begin                                                      // BRK
              c_LCycle = 3'd6;
              case (MCycle)
                3'd1: begin c_Set_Addr_To = AD_SP; c_Write_Data = WD_PCH; c_Write = 1'b1; end
                3'd2: begin c_Dec_S = 1'b1; c_Set_Addr_To = AD_SP; c_Write_Data = WD_PCL; c_Write = 1'b1; end
                3'd3: begin c_Dec_S = 1'b1; c_Set_Addr_To = AD_SP; c_Write_Data = WD_P; c_Write = 1'b1; end
                3'd4: begin c_Dec_S = 1'b1; c_Set_Addr_To = AD_BA; end
                3'd5: begin c_LDDI = 1'b1; c_Set_Addr_To = AD_BA; end
                3'd6: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'h20: begin                                                      // JSR
              c_LCycle = 3'd5;
              case (MCycle)
                3'd1: begin c_Jump = 2'b01; c_LDDI = 1'b1; c_Set_Addr_To = AD_SP; end
                3'd2: begin c_Set_Addr_To = AD_SP; c_Write_Data = WD_PCH; c_Write = 1'b1; end
                3'd3: begin c_Dec_S = 1'b1; c_Set_Addr_To = AD_SP; c_Write_Data = WD_PCL; c_Write = 1'b1; end
                3'd4: c_Dec_S = 1'b1;
                3'd5: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'h40: begin                                                      // RTI
              c_LCycle = 3'd5;
              case (MCycle)
                3'd1: c_Set_Addr_To = AD_SP;
                3'd2: begin c_Inc_S = 1'b1; c_Set_Addr_To = AD_SP; end
                3'd3: begin c_Inc_S = 1'b1; c_Set_Addr_To = AD_SP; c_Set_BusA_To = BA_DI; end
                3'd4: begin c_LDP = 1'b1; c_Inc_S = 1'b1; c_LDDI = 1'b1; c_Set_Addr_To = AD_SP; end
                3'd5: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'h60: begin                                                      // RTS
              c_LCycle = 3'd5;
              case (MCycle)
                3'd1: c_Set_Addr_To = AD_SP;
                3'd2: begin c_Inc_S = 1'b1; c_Set_Addr_To = AD_SP; end
                3'd3: begin c_Inc_S = 1'b1; c_LDDI = 1'b1; c_Set_Addr_To = AD_SP; end
                3'd4: c_Jump = 2'b10;
                3'd5: c_Jump = 2'b01;
                default: ;
              endcase
            end
            8'h08, 8'h48, 8'h5A, 8'hDA: begin                                 // PHP PHA PHY PHX
              c_LCycle = 3'd2;
              case (MCycle)
                3'd1: begin
                  c_Write = 1'b1; c_Set_Addr_To = AD_SP;
                  case (IR[7:6])
                    2'b00: c_Write_Data = WD_P;
                    2'b01: c_Write_Data = IR[4] ? WD_Y : WD_ABC;
                    default: c_Write_Data = WD_X;
                  endcase
                end
                3'd2: c_Dec_S = 1'b1;
                default: ;
              endcase
            end
            8'h28, 8'h68, 8'h7A, 8'hFA: begin                                 // PLP PLA PLY PLX
              c_LCycle = 3'd3;
              c_LDP = (IR[7:4] == 4'h2);
              c_LDA = (IR[7:4] == 4'h6);
              c_LDY = (IR[7:4] == 4'h7);
              c_LDX = (IR[7:4] == 4'hF);
              case (MCycle)
                3'd0: c_SaveP = 1'b1;
                3'd1: begin c_Set_Addr_To = AD_SP; c_LDP = 1'b0; end
                3'd2: begin c_Inc_S = 1'b1; c_Set_Addr_To = AD_SP; c_LDP = 1'b0; end
                3'd3: c_Set_BusA_To = BA_DI;
                default: ;
              endcase
            end
            8'h4C: begin                                                      // JMP a
              c_LCycle = 3'd2;
              case (MCycle)
                3'd1: begin c_Jump = 2'b01; c_LDDI = 1'b1; end
                3'd2: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'h6C: begin                                                      // JMP (a)
              c_LCycle = 3'd5;
              case (MCycle)
                3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
                3'd2: begin c_LDBAH = 1'b1; c_Set_Addr_To = AD_BA; end
                3'd3: begin c_LDDI = 1'b1; c_BAAdd = 2'b01; c_Set_Addr_To = AD_BA; end   // c4 re-reads without carry
                3'd4: begin c_BAAdd = 2'b11; c_Set_Addr_To = AD_BA; end
                3'd5: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'h7C: begin                                                      // JMP (a,x)
              c_LCycle = 3'd5;
              case (MCycle)
                3'd1: begin c_Jump = 2'b01; c_LDBAL = 1'b1; end
                3'd2: begin c_LDBAH = 1'b1; c_Set_BusA_To = BA_X; c_BAAdd = 2'b10; c_PCDec = 1'b1; end
                3'd3: begin c_BAAdd = 2'b11; c_Set_Addr_To = AD_BA; end
                3'd4: begin c_LDDI = 1'b1; c_BAInc16 = 1'b1; c_Set_Addr_To = AD_BA; end
                3'd5: c_Jump = 2'b10;
                default: ;
              endcase
            end
            8'hCB: if (C02_WAISTP) begin                                      // WAI
              c_LCycle = 3'd2;
              if (MCycle == 3'd2) c_Hold = IRQ_n_o & ~NMIAct;
            end
            8'hDB: if (C02_WAISTP) begin                                      // STP
              c_LCycle = 3'd2;
              if (MCycle == 3'd2) c_Hold = 1'b1;
            end
            default: begin
              if (IR[4:0] == 5'b10000 || IR == 8'h80) begin                   // Bxx, BRA
                c_LCycle = (n_Branch || IR == 8'h80) ? 3'd3 : 3'd1;
                case (MCycle)
                  3'd1: begin c_Jump = 2'b01; c_LDDI = 1'b1; end
                  3'd2: begin c_Jump = 2'b11; c_PCAdd = 1'b1; end
                  3'd3: c_PCHfix = 1'b1;
                  default: ;
                endcase
              end else if (IR[3:0] == 4'hF) begin                            // BBR / BBS
                c_LCycle = bbt ? 3'd6 : 3'd4;
                case (MCycle)
                  3'd1: begin c_Jump = 2'b01; c_LDAD = 1'b1; c_Set_Addr_To = AD_ZPG; end
                  3'd2: begin c_LDBAL = 1'b1; c_Set_Addr_To = AD_ZPG; end
                  3'd4: begin c_Jump = 2'b01; c_LDDI = 1'b1; end
                  3'd5: begin c_PCAdd = 1'b1; c_Jump = PCRel[8] ? 2'b00 : 2'b11; end
                  3'd6: begin c_PCAdd = 1'b1; c_Jump = 2'b11; c_PCHfix = 1'b1; end
                  default: ;
                endcase
              end else if (IR[3:0] == 4'hC) begin                            // $5C/$DC/$FC: 3-byte 4-cycle NOPs
                c_LCycle = 3'd3;
                if (MCycle == 3'd1 || MCycle == 3'd3) c_Jump = 2'b01;
              end
            end
          endcase
        end
        default: begin                                                        // implied
          case (IR)
            8'h0A, 8'h2A, 8'h4A, 8'h6A, 8'h1A, 8'h3A: begin c_LDA = 1'b1; c_Set_BusA_To = BA_ABC; end
            8'h8A, 8'h98: c_LDA = 1'b1;
            8'hAA, 8'hA8: if (MCycle == 3'd1) c_Set_BusA_To = BA_ABC;
            8'h88: begin c_LDY = 1'b1; if (MCycle == 3'd1) c_Set_BusA_To = BA_Y; end
            8'hCA: begin c_LDX = 1'b1; if (MCycle == 3'd1) c_Set_BusA_To = BA_X; end
            8'h9A: c_LDS = 1'b1;
            8'hBA: begin c_LDX = 1'b1; if (MCycle == 3'd1) c_Set_BusA_To = BA_S; end
            default: ;
          endcase
        end
      endcase
    end
  end

  // a 1-byte 1-cycle 65C02 NOP is fetched and retired in the same cycle:
  // $x3/$xB, plus $x7/$xF without bit ops; WDC uses $CB/$DB for WAI/STP
  function automatic logic one_cycle_nop(input logic [7:0] op);
    if (op[1:0] != 2'b11)
      one_cycle_nop = 1'b0;
    else if (op[2])
      one_cycle_nop = !C02_BITOPS;
    else
      one_cycle_nop = !(C02_WAISTP && (op == 8'hCB || op == 8'hDB));
  endfunction

  // Mode is latched per instruction like T65; also gating with the pin makes a tied-off Mode fold the
  // whole 65C02 path away combinationally (no reliance on register constant propagation)
  assign c02         = (C02 != 0) && (C02_FIXED || (Mode_r != 2'b00) && (Mode != 2'b00));
  assign LCycle      = c02 ? c_LCycle      : n_LCycle;
  assign ALU_Op      = c02 ? c_ALU_Op      : n_ALU_Op;
  assign Set_BusA_To = c02 ? c_Set_BusA_To : n_Set_BusA_To;
  assign Set_Addr_To = c02 ? c_Set_Addr_To : n_Set_Addr_To;
  assign Write_Data  = c02 ? c_Write_Data  : n_Write_Data;
  assign Jump        = c02 ? c_Jump        : n_Jump;
  assign BAAdd       = c02 ? c_BAAdd       : n_BAAdd;
  assign BAQuirk     = c02 ? 2'b00         : n_BAQuirk;
  assign BreakAtNA   = c02 ? 1'b0          : n_BreakAtNA;
  assign ADAdd       = c02 ? c_ADAdd       : n_ADAdd;
  assign AddY        = c02 ? c_AddY        : n_AddY;
  assign PCAdd       = c02 ? c_PCAdd       : n_PCAdd;
  assign Inc_S       = c02 ? c_Inc_S       : n_Inc_S;
  assign Dec_S       = c02 ? c_Dec_S       : n_Dec_S;
  assign LDA         = c02 ? c_LDA         : n_LDA;
  assign LDP         = c02 ? c_LDP         : n_LDP;
  assign LDX         = c02 ? c_LDX         : n_LDX;
  assign LDY         = c02 ? c_LDY         : n_LDY;
  assign LDS         = c02 ? c_LDS         : n_LDS;
  assign LDDI        = c02 ? c_LDDI        : n_LDDI;
  assign LDALU       = c02 ? c_LDALU       : n_LDALU;
  assign LDAD        = c02 ? c_LDAD        : n_LDAD;
  assign LDBAL       = c02 ? c_LDBAL       : n_LDBAL;
  assign LDBAH       = c02 ? c_LDBAH       : n_LDBAH;
  assign SaveP       = c02 ? c_SaveP       : n_SaveP;
  assign Write       = c02 ? c_Write       : n_Write;
  assign PCDec       = c02 & c_PCDec;
  assign PCHfix      = c02 & c_PCHfix;
  assign BAInc16     = c02 & c_BAInc16;
  assign Hold        = c02 & c_Hold;

  // ================================================================ ALU
  logic       ADC_Z, ADC_C, ADC_V, ADC_N;
  logic [7:0] ADC_Q;
  logic       SBC_Z, SBC_C, SBC_V, SBC_N;
  logic [7:0] SBC_Q, SBX_Q;

  assign dec_en = !NO_DECIMAL && BCD_en_r && P[3];

  // T65's nibble adders carry a '1' in bit 0 to inject the carry; bit 0 of the sums is never used
  /* verilator lint_off UNUSED */
  always_comb begin : alu_adc
    logic [6:0] al, ah;
    logic       c;
    al = {2'b00, BusA_r[3:0], P[0]} + {2'b00, BusB[3:0], 1'b1};
    ah = {2'b00, BusA_r[7:4], al[5]} + {2'b00, BusB[7:4], 1'b1};
    ADC_Z = (al[4:1] == 4'd0) && (ah[4:1] == 4'd0);
    if (al[5:1] > 5'd9 && dec_en)
      al[6:1] = al[6:1] + 6'd6;
    c  = al[6] | al[5];
    ah = {2'b00, BusA_r[7:4], c} + {2'b00, BusB[7:4], 1'b1};
    ADC_N = ah[4];
    ADC_V = (ah[4] ^ BusA_r[7]) & ~(BusA_r[7] ^ BusB[7]);
    if (ah[5:1] > 5'd9 && dec_en)
      ah[6:1] = ah[6:1] + 6'd6;
    ADC_C = ah[6] | ah[5];
    ADC_Q = {ah[4:1], al[4:1]};
  end

  always_comb begin : alu_sbc
    logic [6:0] al;
    logic [5:0] ah;
    logic       c, ct;
    ct = (ALU_Op_r == ALU_AND) || (ALU_Op_r == ALU_ADC) || (ALU_Op_r == ALU_EQ2) ||
         (ALU_Op_r == ALU_SBC) || (ALU_Op_r == ALU_ROL) || (ALU_Op_r == ALU_ROR) ||
         (ALU_Op_r == ALU_INC);
    c  = P[0] | ~ct;
    al = {2'b00, BusA_r[3:0], c} - {2'b00, BusB[3:0], 1'b1};
    ah = {1'b0, BusA_r[7:4], 1'b0} - {1'b0, BusB[7:4], al[5]};
    SBC_Z = (al[4:1] == 4'd0) && (ah[4:1] == 4'd0);
    SBC_C = ~ah[5];
    SBC_V = (ah[4] ^ BusA_r[7]) & (BusA_r[7] ^ BusB[7]);
    SBC_N = ah[4];
    SBX_Q = {ah[4:1], al[4:1]};
    if (dec_en) begin
      if (al[5]) al[5:1] = al[5:1] - 5'd6;
      ah = {1'b0, BusA_r[7:4], 1'b0} - {1'b0, BusB[7:4], al[6]};
      if (ah[5]) ah[5:1] = ah[5:1] - 5'd6;
    end
    SBC_Q = {ah[4:1], al[4:1]};
  end
  /* verilator lint_on UNUSED */

  // 65C02 decimal SBC (Bruce Clark, sequence 3)
  logic [8:0] C02_diff;
  logic       C02_lo_borrow;
  logic [7:0] C02_SBC_Q;
  assign C02_diff      = {1'b0, BusA_r} - {1'b0, BusB} - {8'd0, ~P[0]};
  assign C02_lo_borrow = {1'b0, BusA_r[3:0]} < {1'b0, BusB[3:0]} + {4'd0, ~P[0]};
  assign C02_SBC_Q     = C02_diff[7:0] - (C02_diff[8] ? 8'h60 : 8'h00) - (C02_lo_borrow ? 8'h06 : 8'h00);

  always_comb begin : alu_main
    logic [7:0] q_t, q2_t, bm;
    P_Out = P;
    q_t   = BusA_r;
    q2_t  = BusA_r;
    bm    = 8'h01 << IR[6:4];
    case (ALU_Op_r)
      ALU_OR:  q_t = BusA_r | BusB;
      ALU_AND: q_t = BusA_r & BusB;
      ALU_EOR: q_t = BusA_r ^ BusB;
      ALU_ADC: begin P_Out[6] = ADC_V; P_Out[0] = ADC_C; q_t = ADC_Q; end
      ALU_CMP: P_Out[0] = SBC_C;
      ALU_SAX: begin P_Out[0] = SBC_C; q_t = SBX_Q; end
      ALU_SBC: begin P_Out[6] = SBC_V; P_Out[0] = SBC_C; q_t = (c02 && dec_en) ? C02_SBC_Q : SBC_Q; end
      ALU_TSB: q_t = BusA_r | BusB;
      ALU_TRB: q_t = ~BusA_r & BusB;
      ALU_RSMB: q_t = IR[7] ? (BusA_r | bm) : (BusA_r & ~bm);
      ALU_ASL: begin q_t = {BusA_r[6:0], 1'b0};  P_Out[0] = BusA_r[7]; end
      ALU_ROL: begin q_t = {BusA_r[6:0], P[0]};  P_Out[0] = BusA_r[7]; end
      ALU_LSR: begin q_t = {1'b0, BusA_r[7:1]};  P_Out[0] = BusA_r[0]; end
      ALU_ROR: begin q_t = {P[0], BusA_r[7:1]};  P_Out[0] = BusA_r[0]; end
      ALU_ARR: begin
        q_t = {P[0], BusA_r[7:1] & BusB[7:1]};
        P_Out[6] = q_t[5] ^ q_t[6];
        q2_t = q_t;
        if (dec_en) begin
          if ((BusA_r[3:0] & BusB[3:0]) > 4'd4) q2_t[3:0] = q_t[3:0] + 4'd6;
          if ((BusA_r[7:4] & BusB[7:4]) > 4'd4) begin
            q2_t[7:4] = q_t[7:4] + 4'd6;
            P_Out[0] = 1'b1;
          end else
            P_Out[0] = 1'b0;
        end else
          P_Out[0] = q_t[6];
      end
      ALU_BIT: P_Out[6] = BusB[6];
      ALU_DEC: q_t = BusA_r - 8'd1;
      ALU_INC: q_t = BusA_r + 8'd1;
      default: ;
    endcase

    case (ALU_Op_r)
      ALU_ADC: begin P_Out[7] = c02 ? q_t[7] : ADC_N; P_Out[1] = c02 ? (q_t == 8'd0) : ADC_Z; end
      ALU_SBC: begin P_Out[7] = c02 ? q_t[7] : SBC_N; P_Out[1] = c02 ? (q_t == 8'd0) : SBC_Z; end
      ALU_CMP, ALU_SAX: begin P_Out[7] = SBC_N; P_Out[1] = SBC_Z; end
      ALU_EQ1, ALU_RSMB: ;
      ALU_TSB, ALU_TRB, ALU_BITZ: P_Out[1] = ((BusA_r & BusB) == 8'd0);
      ALU_BIT: begin P_Out[7] = BusB[7]; P_Out[1] = ((BusA_r & BusB) == 8'd0); end
      ALU_ANC: begin P_Out[7] = q_t[7]; P_Out[0] = q_t[7]; P_Out[1] = (q_t == 8'd0); end
      default: begin P_Out[7] = q_t[7]; P_Out[1] = (q_t == 8'd0); end
    endcase

    ALU_Q = (ALU_Op_r == ALU_ARR) ? q2_t : q_t;
  end

  // ================================================================ top level
  assign o_NMI_ack  = NMIAct;
  assign really_rdy = Rdy | ~WRn_i;
  assign o_Sync     = (MCycle == 3'd0);
  assign o_EF       = EF_i;
  assign o_MF       = MF_i;
  assign o_XF       = XF_i;
  assign o_R_W_n    = WRn_i;
  assign o_ML_n     = ~(IR[7:6] != 2'b10 && IR[2:1] == 2'b11 && MCycle[2:1] != 2'b00);
  assign o_VP_n     = ~(IRQCycle && (MCycle == 3'd5 || MCycle == 3'd6));
  assign o_VDA      = (Set_Addr_To_r != AD_PBR);
  assign o_VPA      = ~Jump[1];
  assign o_DEBUG    = {IR, ABC, X, Y, S[7:0], P};
  assign o_Regs     = {PC, S, P, Y, X, ABC};

  // the 65xx design requires at least two clock cycles before starting its reset sequence
  always_ff @(posedge Clk or negedge Res_n) begin
    if (!Res_n) begin
      Res_n_i <= 1'b0;
      Res_n_d <= 1'b0;
    end else begin
      Res_n_i <= Res_n_d;
      Res_n_d <= 1'b1;
    end
  end

  always_ff @(posedge Clk or negedge Res_n_i) begin
    if (!Res_n_i) begin
      PC            <= 16'd0;
      IR            <= 8'd0;
      S             <= 16'd0;
      PBR           <= 8'd0;
      DBR           <= 8'd0;
      Mode_r        <= 2'b00;
      BCD_en_r      <= 1'b1;
      ALU_Op_r      <= ALU_BIT;
      Write_Data_r  <= WD_DL;
      Set_Addr_To_r <= AD_PBR;
      WRn_i         <= 1'b1;
      EF_i          <= 1'b1;
      MF_i          <= 1'b1;
      XF_i          <= 1'b1;
    end else if (Enable && really_rdy) begin
      WRn_i <= ~Write | RstCycle;
      PBR   <= 8'hFF;
      DBR   <= 8'hFF;
      EF_i  <= 1'b0;
      MF_i  <= 1'b0;
      XF_i  <= 1'b0;

      if (MCycle == CYC_SYNC) begin
        Mode_r <= Mode;
        BCD_en_r <= BCD_en;
        if (!IRQCycle && !NMICycle) PC <= PC + 16'd1;
        IR <= (IRQCycle || NMICycle) ? 8'h00 : DI;
        if (LDS) S[7:0] <= ALU_Q;
      end

      ALU_Op_r      <= ALU_Op;
      Write_Data_r  <= Write_Data;
      Set_Addr_To_r <= Break ? AD_PBR : Set_Addr_To;

      if (Inc_S) S <= S + 16'd1;
      if (Dec_S && !RstCycle) S <= S - 16'd1;

      if (IR == 8'h00 && MCycle == 3'd1 && !IRQCycle && !NMICycle) PC <= PC + 16'd1;

      case (Jump)
        2'b01: PC <= PC + 16'd1;
        2'b10: PC <= {DI, DL};
        2'b11: begin
          if (PCAdder[8] && !c02) PC[15:8] <= DL[7] ? PC[15:8] - 8'd1 : PC[15:8] + 8'd1;
          PC[7:0] <= PCAdder[7:0];
        end
        default: ;
      endcase
      if (PCHfix) PC[15:8] <= DL[7] ? PC[15:8] - 8'd1 : PC[15:8] + 8'd1;
      if (PCDec)  PC <= PC - 16'd1;
    end
  end

  // T65 never resets these; they hold their value while Res_n_i is low (Res_n_i acts as a synchronous enable)
  /* verilator lint_off SYNCASYNCNET */
  always_ff @(posedge Clk) begin
    if (Res_n_i && Enable) begin
      if (MCycle == CYC_SYNC)
        rdy_mod <= 1'b0;
      else if (((MCycle == 3'd3 && IR != 8'h93) || (MCycle == 3'd4 && IR == 8'h93)) && !Rdy)
        rdy_mod <= 1'b1;
    end
  end

  assign PCRel   = {1'b0, PC[7:0]} + {DL[7], DL};
  assign PCAdder = PCAdd ? PCRel : {1'b0, PC[7:0]};

  // flags
  always_ff @(posedge Clk or negedge Res_n_i) begin
    if (!Res_n_i)
      P <= 8'h00;
    else begin
      if (Enable && really_rdy) begin : p_upd
        logic [7:0] tmpP;
        tmpP = P;
        if (MCycle == CYC_SYNC && (LDA || LDX || LDY)) tmpP = P_Out;
        if (SaveP) tmpP = P_Out;
        if (LDP)   tmpP = ALU_Q;
        if (IR[4:0] == 5'b11000) begin
          case (IR[7:5])
            3'b000: tmpP[0] = 1'b0;      // CLC
            3'b001: tmpP[0] = 1'b1;      // SEC
            3'b010: tmpP[2] = 1'b0;      // CLI
            3'b011: tmpP[2] = 1'b1;      // SEI
            3'b101: tmpP[6] = 1'b0;      // CLV
            3'b110: tmpP[3] = 1'b0;      // CLD
            3'b111: tmpP[3] = 1'b1;      // SED
            default: ;
          endcase
        end
        tmpP[4] = 1'b1;
        if (IR == 8'h00 && MCycle == 3'd4 && !RstCycle) begin
          tmpP[2] = 1'b1;
          if (c02) tmpP[3] = 1'b0;
        end
        if (RstCycle) begin
          tmpP[2] = 1'b1;
          tmpP[3] = 1'b0;
        end
        tmpP[5] = 1'b1;
        P <= tmpP;
      end
      if (SO_n_o && !SO_n) P[6] <= 1'b1;
    end
  end

  always_ff @(posedge Clk) begin
    if (Res_n_i) begin
      if (Enable) begin
        if (really_rdy && MCycle == CYC_SYNC) begin
          if (LDA) ABC <= ALU_Q;
          if (LDX) X   <= ALU_Q;
          if (LDY) Y   <= ALU_Q;
        end
        // interrupt inputs are not sampled during the operand cycle of a branch
        if (IR[4:0] != 5'b10000 || Jump != 2'b01 || !really_rdy) IRQ_n_o <= IRQ_n;
        if (IR[4:0] != 5'b10000 || Jump != 2'b01) NMI_n_o <= NMI_n;
      end
      SO_n_o <= SO_n;
    end
  end

  // ================================================================ buses
  always_ff @(posedge Clk or negedge Res_n_i) begin
    if (!Res_n_i) begin
      BusA_r <= 8'd0;
      BusB   <= 8'd0;
      BusB_r <= 8'd0;
      AD     <= 8'd0;
      BAL    <= 9'd0;
      BAH    <= 8'd0;
      DL     <= 8'd0;
    end else if (Enable && really_rdy) begin
      BusA_r <= BusA;
      BusB   <= DI;
      if (Set_Addr_To_r == AD_PBR || Set_Addr_To_r == AD_ZPG) BusB_r <= DI + 8'd1;

      case (BAAdd)
        2'b01: begin AD <= AD + 8'd1; BAL <= BAL + 9'd1; end
        2'b10: BAL <= {1'b0, BAL[7:0]} + {1'b0, BusA};
        2'b11: if (BAL[8]) begin
          case (BAQuirk)
            2'b00: BAH <= BAH + 8'd1;
            2'b01: BAH <= (BAH + 8'd1) & DO_r;
            2'b10: BAH <= DO_r;
            default: ;
          endcase
        end
        default: ;
      endcase

      if (BAInc16) {BAH, BAL[7:0]} <= {BAH, BAL[7:0]} + 16'd1;
      if (ADAdd) AD <= AD + (AddY ? Y : X);

      if (IR == 8'h00) begin
        BAL <= 9'h1FF;
        BAH <= 8'hFF;
        if (RstCycle)
          BAL[2:0] <= 3'b100;
        else if (NMICycle || (NMIAct && MCycle == 3'd4) || NMI_entered)
          BAL[2:0] <= 3'b010;
        else
          BAL[2:0] <= 3'b110;
        if (Set_Addr_To_r == AD_BA) BAL[0] <= 1'b1;
      end

      if (LDDI)  DL <= DI;
      if (LDALU) DL <= ALU_Q;
      if (LDAD)  AD <= DI;
      if (LDBAL) BAL[7:0] <= DI;
      if (LDBAL && c02) BAL[8] <= 1'b0;   // T65 keeps a stale carry here; the 65C02 table relies on a clean one
      if (LDBAH) BAH <= DI;
    end
  end

  always_ff @(posedge Clk) begin
    if (Res_n_i && Enable && really_rdy)
      NMI_entered <= (IR == 8'h00 && MCycle == 3'd4 && !RstCycle &&
                      (NMICycle || NMIAct || NMI_entered)) ? 1'b1 : 1'b0;
  end

  assign Break = (BreakAtNA & ~BAL[8]) | (PCAdd & ~PCAdder[8]);

  always_comb begin
    case (Set_BusA_To)
      BA_DI:   BusA = DI;
      BA_ABC:  BusA = ABC;
      BA_X:    BusA = X;
      BA_Y:    BusA = Y;
      BA_S:    BusA = S[7:0];
      BA_P:    BusA = P;
      BA_DA:   BusA = ABC & DI;
      BA_DAO:  BusA = (ABC | 8'hEE) & DI;
      BA_DAX:  BusA = (ABC | 8'hEE) & DI & X;
      default: BusA = ABC & X;   // BA_AAX
    endcase
  end

  always_comb begin
    case (Set_Addr_To_r)
      AD_SP:   o_A = {16'h0001, S[7:0]};
      AD_ZPG:  o_A = {DBR, 8'h00, AD};
      AD_BA:   o_A = {8'h00, BAH, BAL[7:0]};
      default: o_A = {PBR, PC[15:8], c02 ? PC[7:0] : PCAdder[7:0]};
    endcase
  end

  // P pushed with B clear on IRQ/NMI entry
  assign PwithB = (IRQCycle || NMICycle) ? (P & 8'hEF) : P;
  assign o_DO   = DO_r;

  always_comb begin
    case (Write_Data_r)
      WD_DL:   DO_r = DL;
      WD_ABC:  DO_r = ABC;
      WD_X:    DO_r = X;
      WD_Y:    DO_r = Y;
      WD_S:    DO_r = S[7:0];
      WD_P:    DO_r = PwithB;
      WD_PCL:  DO_r = PC[7:0];
      WD_PCH:  DO_r = PC[15:8];
      WD_AX:   DO_r = ABC & X;
      WD_AXB:  DO_r = ABC & X & BusB_r;
      WD_XB:   DO_r = X & BusB_r;
      WD_YB:   DO_r = Y & BusB_r;
      default: DO_r = 8'h00;       // WD_ZERO (STZ)
    endcase
  end

  // ================================================================ state machine
  always_ff @(posedge Clk or negedge Res_n_i) begin
    if (!Res_n_i) begin
      MCycle   <= 3'd1;
      RstCycle <= 1'b1;
      IRQCycle <= 1'b0;
      NMICycle <= 1'b0;
      NMIAct   <= 1'b0;
    end else if (Enable) begin
      if (really_rdy && !Hold) begin
        if (c02 && MCycle == CYC_SYNC && !IRQCycle && !NMICycle && one_cycle_nop(DI))
          MCycle <= CYC_SYNC;
        else if (MCycle == LCycle || Break) begin
          MCycle   <= 3'd0;
          RstCycle <= 1'b0;
          IRQCycle <= 1'b0;
          NMICycle <= 1'b0;
          if (NMIAct && IR != 8'h00) begin
            NMICycle <= 1'b1;
            NMIAct   <= 1'b0;
          end else if (!IRQ_n_o && !P[2])
            IRQCycle <= 1'b1;
        end else
          MCycle <= MCycle + 3'd1;
      end
      if (NMI_n_o && !NMI_n && (IR[4:0] != 5'b10000 || Jump != 2'b01)) NMIAct <= 1'b1;
      if (NMI_entered) NMIAct <= 1'b0;
    end
  end

  // ================================================================ port selection
  generate
    if (C816) begin : g_c816
      // T65's Regs / DEBUG layouts carry the low bytes; D, DBR, PBR, E and the high bytes are not exported there
      /* verilator lint_off UNUSED */
      logic [15:0] r_pc, r_c, r_x, r_y, r_s, r_d;
      logic [7:0]  r_dbr, r_pbr, r_p, r_ir;
      logic        r_e, wait_n;
      /* verilator lint_on UNUSED */
      t65sv816 u_816 (
        .Clk(Clk), .Enable(Enable), .Res_n(Res_n), .Rdy(Rdy), .Abort_n(Abort_n), .IRQ_n(IRQ_n), .NMI_n(NMI_n),
        .DI(DI), .A(A), .DO(DO), .R_W_n(R_W_n), .VDA(VDA), .VPA(VPA), .VP_n(VP_n), .ML_n(ML_n), .E(EF), .MF(MF),
        .XF(XF), .Sync(Sync), .Wait_n(wait_n), .NMI_ack(NMI_ack), .Regs_PC(r_pc), .Regs_C(r_c), .Regs_X(r_x),
        .Regs_Y(r_y), .Regs_S(r_s), .Regs_D(r_d), .Regs_DBR(r_dbr), .Regs_PBR(r_pbr), .Regs_P(r_p), .Regs_E(r_e),
        .Regs_IR(r_ir));
      assign Regs  = {r_pc, r_s, r_p, r_y[7:0], r_x[7:0], r_c[7:0]};
      assign DEBUG = {r_ir, r_c[7:0], r_x[7:0], r_y[7:0], r_s[7:0], r_p};
    end else begin : g_6502
      assign A = o_A;         assign DO = o_DO;       assign R_W_n = o_R_W_n; assign Sync = o_Sync;
      assign EF = o_EF;       assign MF = o_MF;       assign XF = o_XF;       assign ML_n = o_ML_n;
      assign VP_n = o_VP_n;   assign VDA = o_VDA;     assign VPA = o_VPA;     assign NMI_ack = o_NMI_ack;
      assign Regs = o_Regs;   assign DEBUG = o_DEBUG;
    end
  endgenerate

endmodule

// t65sv816: W65C816S core (emulation + native modes, ABORT, WAI/STP, MVN/MVP), bus-cycle exact against
// SingleStepTests 65816. Part of t65sv; derived-work notice and licence: see t65sv.sv.
//
// Sequencer: every instruction is a short list of micro-ops (one per bus cycle, index K = 1..), looked up
// from the opcode. A micro-op may carry a skip condition (8-bit width, DL = 0, no index carry, branch not
// taken, ...); skipped micro-ops take no time. K reaching an END entry is the opcode fetch of the next
// instruction (or the first cycle of an interrupt).
module t65sv816 (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  input  logic        Abort_n,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  input  logic [7:0]  DI,
  output logic [23:0] A,
  output logic [7:0]  DO,
  output logic        R_W_n,
  output logic        VDA,
  output logic        VPA,
  output logic        VP_n,     // vector pull
  output logic        ML_n,     // memory lock
  output logic        E,        // emulation flag pin
  output logic        MF,       // M as seen on the MX pin
  output logic        XF,       // X as seen on the MX pin
  output logic        Sync,     // opcode fetch (VDA & VPA)
  output logic        Wait_n,   // low while WAI waits (the chip pulls RDY low)
  output logic        NMI_ack,  // one-cycle pulse when an NMI is taken
  output logic [15:0] Regs_PC,
  output logic [15:0] Regs_C,
  output logic [15:0] Regs_X,
  output logic [15:0] Regs_Y,
  output logic [15:0] Regs_S,
  output logic [15:0] Regs_D,
  output logic [7:0]  Regs_DBR,
  output logic [7:0]  Regs_PBR,
  output logic [7:0]  Regs_P,
  output logic        Regs_E,
  output logic [7:0]  Regs_IR
);
  // ------------------------------------------------------------------ micro-op kinds
  localparam logic [5:0]
    U_END  = 6'd0,   // opcode fetch (next instruction)
    U_OP1  = 6'd1,   // operand byte 1 -> OPR[7:0], DAT[7:0]
    U_OP2  = 6'd2,   // operand byte 2 -> OPR[15:8], DAT[15:8]
    U_OP3  = 6'd3,   // operand byte 3 -> BNK
    U_IMM1 = 6'd4,   // immediate low byte (executes if 8-bit)
    U_IMM2 = 6'd5,   // immediate high byte (executes)
    U_IOPC = 6'd6,   // internal, address PBR:PC
    U_IO   = 6'd7,   // internal, previous address
    U_IOX  = 6'd8,   // internal, index-carry address (bank:high:(low+index) without the carry)
    U_DRL  = 6'd9,   // data read EA (executes if 8-bit)
    U_DRH  = 6'd10,  // data read EA+1 (executes)
    U_DWL  = 6'd11,  // data write EA
    U_DWH  = 6'd12,  // data write EA+1
    U_MRL  = 6'd13,  // read-modify-write: read EA
    U_MRH  = 6'd14,  //   read EA+1
    U_MOD  = 6'd15,  //   modify (native: internal; emulation: rewrite old value)
    U_MWH  = 6'd16,  //   write EA+1
    U_MWL  = 6'd17,  //   write EA
    U_PRL  = 6'd18,  // pointer read EA -> DAT[7:0]
    U_PRH  = 6'd19,  // pointer read EA+1 -> DAT[15:8]
    U_PRB  = 6'd20,  // pointer read EA+2 -> BNK
    U_PSHH = 6'd21,  // push high byte of the push source
    U_PSHL = 6'd22,  // push low byte
    U_PSHK = 6'd23,  // push PBR
    U_PSHB = 6'd24,  // push DBR
    U_PSHP = 6'd25,  // push P
    U_PULL = 6'd26,  // pull -> DAT[7:0]
    U_PULH = 6'd27,  // pull -> DAT[15:8]
    U_PULB = 6'd28,  // pull -> BNK
    U_PULP = 6'd29,  // pull -> P
    U_VECL = 6'd30,  // vector low
    U_VECH = 6'd31,  // vector high
    U_MVR  = 6'd32,  // block move read
    U_MVW  = 6'd33,  // block move write
    U_WAIT = 6'd34,  // WAI: waiting for an interrupt
    U_STOP = 6'd35;  // STP: stopped until reset

  // skip conditions
  localparam logic [3:0] S_NO = 4'd0, S_W8 = 4'd1, S_DL0 = 4'd2, S_IDX = 4'd3, S_NT = 4'd4, S_BPX = 4'd5,
                         S_EMU = 4'd6;

  // end-of-cycle actions
  localparam logic [4:0] A_NONE = 5'd0, A_EADP = 5'd1, A_EADPX = 5'd2, A_EADPY = 5'd3,   // EADPX/Y: index step of d,x d,y (d,x)
                         A_EASR = 5'd4,
                         A_EAABS = 5'd5, A_EAABX = 5'd6, A_EAABY = 5'd7, A_EALNG = 5'd8, A_EALNX = 5'd9,
                         A_EAPTR = 5'd10, A_EAPTY = 5'd11, A_EAPTL = 5'd12, A_EAPLY = 5'd13, A_EAAB0 = 5'd14,
                         A_EAPBX = 5'd15, A_JMP = 5'd16, A_JML = 5'd17, A_JMPI = 5'd18, A_JMLI = 5'd19,
                         A_JSR = 5'd20, A_JSL = 5'd21, A_RTS = 5'd22, A_RTL = 5'd23, A_BR = 5'd24,
                         A_BRL = 5'd25, A_PER = 5'd26, A_EXEC = 5'd27, A_PCI = 5'd28, A_MV = 5'd29,
                         A_VEC = 5'd30, A_PBR = 5'd31;

  // addressing modes of the data instructions
  localparam logic [4:0] AM_IMM = 5'd1, AM_DP = 5'd2, AM_DPX = 5'd3, AM_DPY = 5'd4,
                         AM_DPI = 5'd5, AM_DPIL = 5'd6, AM_DPXI = 5'd7, AM_DPIY = 5'd8, AM_DPILY = 5'd9,
                         AM_ABS = 5'd10, AM_ABX = 5'd11, AM_ABY = 5'd12, AM_ABL = 5'd13, AM_ALX = 5'd14,
                         AM_SR = 5'd15, AM_SRIY = 5'd16, AM_SPC = 5'd17;
  localparam logic [1:0] K_RD = 2'd0, K_WR = 2'd1, K_RMW = 2'd2;
  localparam logic [4:0] O_LDA = 5'd0, O_LDX = 5'd1, O_LDY = 5'd2, O_STA = 5'd3, O_STX = 5'd4, O_STY = 5'd5,
                         O_STZ = 5'd6, O_ORA = 5'd7, O_AND = 5'd8, O_EOR = 5'd9, O_ADC = 5'd10, O_SBC = 5'd11,
                         O_CMP = 5'd12, O_CPX = 5'd13, O_CPY = 5'd14, O_BIT = 5'd15, O_ASL = 5'd16,
                         O_ROL = 5'd17, O_LSR = 5'd18, O_ROR = 5'd19, O_INC = 5'd20, O_DEC = 5'd21,
                         O_TSB = 5'd22, O_TRB = 5'd23, O_BITI = 5'd24;
  // EA increment wrap
  localparam logic [1:0] W24 = 2'd0, W16 = 2'd1, W8 = 2'd2;
  // interrupt kinds
  localparam logic [2:0] I_IRQ = 3'd0, I_NMI = 3'd1, I_ABT = 3'd2, I_RES = 3'd3;

  // ------------------------------------------------------------------ state
  logic [15:0] C, X, Y, S, D, PC;
  logic [7:0]  DBR, PBR, P;
  logic        Ef;
  logic [7:0]  IR;
  logic [3:0]  K;
  logic        INTR;         // running sequence is a hardware interrupt / reset (IR = 00)
  logic [2:0]  IK;
  logic [23:0] EA, IAD, LA;
  logic [1:0]  EAW;
  logic [15:0] OPR, DAT, SP;
  logic [7:0]  BNK;
  logic        CX;           // index / branch page carry
  logic        sM, sX, sE;   // M / X / E as at the start of the instruction (pins)
  logic        nmi_pend, nmi_d, abt_pend;
  logic        res_pend;     // reset sequence pending (taken at the first fetch after reset)
  // ABORT: architectural state at the start of the instruction
  logic [15:0] aC, aX, aY, aS, aD, aPC;
  logic [7:0]  aDBR, aPBR, aP;
  logic        aE;

  logic Mf, Xf;
  assign Mf = Ef | P[5];
  assign Xf = Ef | P[4];

  assign Regs_PC = PC; assign Regs_C = C; assign Regs_X = X; assign Regs_Y = Y; assign Regs_S = S;
  assign Regs_D = D; assign Regs_DBR = DBR; assign Regs_PBR = PBR; assign Regs_P = P; assign Regs_E = Ef;
  assign Regs_IR = IR;

  // ------------------------------------------------------------------ decode (data instructions)
  logic [4:0] am, op;
  logic [1:0] kd;
  logic       wx;
  always_comb begin
    am = AM_SPC; op = O_LDA; kd = K_RD; wx = 1'b0;
    if (IR[1:0] == 2'b01 || IR[4:0] == 5'b10010 || (IR[1:0] == 2'b11 && IR[2]) || IR[3:0] == 4'h3) begin
      case (IR[7:5])
        3'd0: op = O_ORA; 3'd1: op = O_AND; 3'd2: op = O_EOR; 3'd3: op = O_ADC;
        3'd4: begin op = O_STA; kd = K_WR; end
        3'd5: op = O_LDA; 3'd6: op = O_CMP; default: op = O_SBC;
      endcase
      case (IR[4:0])
        5'h01: am = AM_DPXI;  5'h11: am = AM_DPIY;  5'h12: am = AM_DPI;
        5'h03: am = AM_SR;    5'h13: am = AM_SRIY;
        5'h05: am = AM_DP;    5'h15: am = AM_DPX;
        5'h07: am = AM_DPIL;  5'h17: am = AM_DPILY;
        5'h09: am = AM_IMM;   5'h19: am = AM_ABY;
        5'h0D: am = AM_ABS;   5'h1D: am = AM_ABX;
        5'h0F: am = AM_ABL;   5'h1F: am = AM_ALX;
        default: am = AM_SPC;
      endcase
      if (IR == 8'h89) begin op = O_BITI; kd = K_RD; end
    end else if (IR[1:0] == 2'b10 && IR[2]) begin
      case (IR[7:5])
        3'd0: begin op = O_ASL; kd = K_RMW; end
        3'd1: begin op = O_ROL; kd = K_RMW; end
        3'd2: begin op = O_LSR; kd = K_RMW; end
        3'd3: begin op = O_ROR; kd = K_RMW; end
        3'd4: begin op = O_STX; kd = K_WR; wx = 1'b1; end
        3'd5: begin op = O_LDX; kd = K_RD; wx = 1'b1; end
        3'd6: begin op = O_DEC; kd = K_RMW; end
        default: begin op = O_INC; kd = K_RMW; end
      endcase
      case ({IR[4], IR[3]})
        2'b00: am = AM_DP;
        2'b10: am = (IR[7:6] == 2'b10) ? AM_DPY : AM_DPX;
        2'b01: am = AM_ABS;
        default: am = (IR == 8'hBE) ? AM_ABY : AM_ABX;
      endcase
      if (IR == 8'h9E) begin op = O_STZ; kd = K_WR; wx = 1'b0; end
    end else begin
      case (IR)
        8'h04: begin am = AM_DP;  op = O_TSB; kd = K_RMW; end
        8'h0C: begin am = AM_ABS; op = O_TSB; kd = K_RMW; end
        8'h14: begin am = AM_DP;  op = O_TRB; kd = K_RMW; end
        8'h1C: begin am = AM_ABS; op = O_TRB; kd = K_RMW; end
        8'h24: begin am = AM_DP;  op = O_BIT; end
        8'h34: begin am = AM_DPX; op = O_BIT; end
        8'h2C: begin am = AM_ABS; op = O_BIT; end
        8'h3C: begin am = AM_ABX; op = O_BIT; end
        8'h64: begin am = AM_DP;  op = O_STZ; kd = K_WR; end
        8'h74: begin am = AM_DPX; op = O_STZ; kd = K_WR; end
        8'h9C: begin am = AM_ABS; op = O_STZ; kd = K_WR; end
        8'h84: begin am = AM_DP;  op = O_STY; kd = K_WR; wx = 1'b1; end
        8'h94: begin am = AM_DPX; op = O_STY; kd = K_WR; wx = 1'b1; end
        8'h8C: begin am = AM_ABS; op = O_STY; kd = K_WR; wx = 1'b1; end
        8'hA4: begin am = AM_DP;  op = O_LDY; wx = 1'b1; end
        8'hB4: begin am = AM_DPX; op = O_LDY; wx = 1'b1; end
        8'hAC: begin am = AM_ABS; op = O_LDY; wx = 1'b1; end
        8'hBC: begin am = AM_ABX; op = O_LDY; wx = 1'b1; end
        8'hC4: begin am = AM_DP;  op = O_CPY; wx = 1'b1; end
        8'hCC: begin am = AM_ABS; op = O_CPY; wx = 1'b1; end
        8'hE4: begin am = AM_DP;  op = O_CPX; wx = 1'b1; end
        8'hEC: begin am = AM_ABS; op = O_CPX; wx = 1'b1; end
        8'hA0: begin am = AM_IMM; op = O_LDY; wx = 1'b1; end
        8'hA2: begin am = AM_IMM; op = O_LDX; wx = 1'b1; end
        8'hC0: begin am = AM_IMM; op = O_CPY; wx = 1'b1; end
        8'hE0: begin am = AM_IMM; op = O_CPX; wx = 1'b1; end
        // index-width stack ops
        8'hDA, 8'hFA, 8'h5A, 8'h7A: wx = 1'b1;
        default: am = AM_SPC;
      endcase
    end
  end

  // operand width of the running instruction (PLD / PEA / PEI / PER / PHD and the 16-bit transfers are 16-bit
  // regardless; PLB is 8-bit)
  logic w16;
  always_comb begin
    case (IR)
      8'h0B, 8'h2B, 8'hD4, 8'hF4, 8'h62: w16 = 1'b1;
      8'hAB: w16 = 1'b0;
      default: w16 = wx ? !Xf : !Mf;
    endcase
  end

  // "new" 65816 stack instructions: in emulation they address the stack with the full 16-bit S
  logic newstk;
  always_comb begin
    case (IR)
      8'hAB, 8'h0B, 8'h2B, 8'h62, 8'hD4, 8'hF4, 8'h22, 8'h6B, 8'hFC: newstk = !INTR;
      default: newstk = 1'b0;
    endcase
  end

  // ------------------------------------------------------------------ micro-program
  function automatic logic [14:0] mk(input logic [5:0] kind, input logic [3:0] sk, input logic [4:0] act);
    mk = {act, sk, kind};
  endfunction

  // data part of a data instruction, starting at step d0
  function automatic logic [14:0] dpart(input logic [1:0] kd_, input logic [3:0] i);
    dpart = mk(U_END, S_NO, A_NONE);
    case (kd_)
      K_RD: case (i)
              4'd0: dpart = mk(U_DRL, S_NO, A_NONE);
              4'd1: dpart = mk(U_DRH, S_W8, A_NONE);
              default: ;
            endcase
      K_WR: case (i)
              4'd0: dpart = mk(U_DWL, S_NO, A_NONE);
              4'd1: dpart = mk(U_DWH, S_W8, A_NONE);
              default: ;
            endcase
      default: case (i)
              4'd0: dpart = mk(U_MRL, S_NO, A_NONE);
              4'd1: dpart = mk(U_MRH, S_W8, A_NONE);
              4'd2: dpart = mk(U_MOD, S_NO, A_NONE);
              4'd3: dpart = mk(U_MWH, S_W8, A_NONE);
              4'd4: dpart = mk(U_MWL, S_NO, A_NONE);
              default: ;
            endcase
    endcase
  endfunction

  function automatic logic [14:0] uprog(input logic [7:0] ir, input logic [3:0] k, input logic intr,
                                        input logic [4:0] am_, input logic [1:0] kd_);
    logic [3:0] ixs;   // skip condition of the index-carry cycle
    uprog = mk(U_END, S_NO, A_NONE);
    ixs = (kd_ == K_RD) ? S_IDX : S_NO;
    if (am_ != AM_SPC) begin
      case (am_)
        AM_IMM:  case (k)
                   4'd1: uprog = mk(U_IMM1, S_NO, A_NONE);
                   4'd2: uprog = mk(U_IMM2, S_W8, A_NONE);
                   default: ;
                 endcase
        AM_DP:   case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   default: uprog = dpart(kd_, k - 4'd3);
                 endcase
        AM_DPX, AM_DPY:
                 case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   4'd3: uprog = mk(U_IO, S_NO, (am_ == AM_DPX) ? A_EADPX : A_EADPY);
                   default: uprog = dpart(kd_, k - 4'd4);
                 endcase
        AM_SR:   case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EASR);
                   4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                   default: uprog = dpart(kd_, k - 4'd3);
                 endcase
        AM_DPI:  case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   4'd3: uprog = mk(U_PRL, S_NO, A_NONE);
                   4'd4: uprog = mk(U_PRH, S_NO, A_EAPTR);
                   default: uprog = dpart(kd_, k - 4'd5);
                 endcase
        AM_DPXI: case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   4'd3: uprog = mk(U_IO, S_NO, A_EADPX);
                   4'd4: uprog = mk(U_PRL, S_NO, A_NONE);
                   4'd5: uprog = mk(U_PRH, S_NO, A_EAPTR);
                   default: uprog = dpart(kd_, k - 4'd6);
                 endcase
        AM_DPIY: case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   4'd3: uprog = mk(U_PRL, S_NO, A_NONE);
                   4'd4: uprog = mk(U_PRH, S_NO, A_EAPTY);
                   4'd5: uprog = mk(U_IOX, ixs, A_NONE);
                   default: uprog = dpart(kd_, k - 4'd6);
                 endcase
        AM_DPIL, AM_DPILY:
                 case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
                   4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
                   4'd3: uprog = mk(U_PRL, S_NO, A_NONE);
                   4'd4: uprog = mk(U_PRH, S_NO, A_NONE);
                   4'd5: uprog = mk(U_PRB, S_NO, (am_ == AM_DPIL) ? A_EAPTL : A_EAPLY);
                   default: uprog = dpart(kd_, k - 4'd6);
                 endcase
        AM_SRIY: case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_EASR);
                   4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                   4'd3: uprog = mk(U_PRL, S_NO, A_NONE);
                   4'd4: uprog = mk(U_PRH, S_NO, A_EAPTY);
                   4'd5: uprog = mk(U_IO, S_NO, A_NONE);
                   default: uprog = dpart(kd_, k - 4'd6);
                 endcase
        AM_ABS:  case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
                   4'd2: uprog = mk(U_OP2, S_NO, A_EAABS);
                   default: uprog = dpart(kd_, k - 4'd3);
                 endcase
        AM_ABX, AM_ABY:
                 case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
                   4'd2: uprog = mk(U_OP2, S_NO, (am_ == AM_ABX) ? A_EAABX : A_EAABY);
                   4'd3: uprog = mk(U_IOX, ixs, A_NONE);
                   default: uprog = dpart(kd_, k - 4'd4);
                 endcase
        default: // AM_ABL, AM_ALX
                 case (k)
                   4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
                   4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
                   4'd3: uprog = mk(U_OP3, S_NO, (am_ == AM_ABL) ? A_EALNG : A_EALNX);
                   default: uprog = dpart(kd_, k - 4'd4);
                 endcase
      endcase
    end else begin
      case (ir)
        8'h00, 8'h02: // BRK, COP, hardware interrupts and reset
          case (k)
            4'd1: uprog = intr ? mk(U_IOPC, S_NO, A_NONE) : mk(U_OP1, S_NO, A_NONE);
            4'd2: uprog = mk(U_PSHK, S_EMU, A_NONE);
            4'd3: uprog = mk(U_PSHH, S_NO, A_NONE);
            4'd4: uprog = mk(U_PSHL, S_NO, A_NONE);
            4'd5: uprog = mk(U_PSHP, S_NO, A_NONE);
            4'd6: uprog = mk(U_VECL, S_NO, A_NONE);
            4'd7: uprog = mk(U_VECH, S_NO, A_VEC);
            default: ;
          endcase
        8'h08: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_PSHP, S_NO, A_NONE); default: ; endcase
        8'h8B: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_PSHB, S_NO, A_NONE); default: ; endcase
        8'h4B: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_PSHK, S_NO, A_NONE); default: ; endcase
        8'h0B, 8'h48, 8'hDA, 8'h5A: // PHD, PHA, PHX, PHY
          case (k)
            4'd1: uprog = mk(U_IOPC, S_NO, A_NONE);
            4'd2: uprog = mk(U_PSHH, S_W8, A_NONE);
            4'd3: uprog = mk(U_PSHL, S_NO, A_NONE);
            default: ;
          endcase
        8'h28: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PULP, S_NO, A_NONE); default: ; endcase
        8'h2B, 8'h68, 8'hFA, 8'h7A, 8'hAB: // PLD, PLA, PLX, PLY, PLB
          case (k)
            4'd1: uprog = mk(U_IOPC, S_NO, A_NONE);
            4'd2: uprog = mk(U_IO, S_NO, A_NONE);
            4'd3: uprog = mk(U_PULL, S_NO, A_NONE);
            4'd4: uprog = mk(U_PULH, S_W8, A_NONE);
            default: ;
          endcase
        8'hF4: // PEA
          case (k)
            4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
            4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
            4'd3: uprog = mk(U_PSHH, S_NO, A_NONE);
            4'd4: uprog = mk(U_PSHL, S_NO, A_NONE);
            default: ;
          endcase
        8'hD4: // PEI
          case (k)
            4'd1: uprog = mk(U_OP1, S_NO, A_EADP);
            4'd2: uprog = mk(U_IO, S_DL0, A_NONE);
            4'd3: uprog = mk(U_PRL, S_NO, A_NONE);
            4'd4: uprog = mk(U_PRH, S_NO, A_NONE);
            4'd5: uprog = mk(U_PSHH, S_NO, A_NONE);
            4'd6: uprog = mk(U_PSHL, S_NO, A_NONE);
            default: ;
          endcase
        8'h62: // PER
          case (k)
            4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
            4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
            4'd3: uprog = mk(U_IO, S_NO, A_PER);
            4'd4: uprog = mk(U_PSHH, S_NO, A_NONE);
            4'd5: uprog = mk(U_PSHL, S_NO, A_NONE);
            default: ;
          endcase
        8'hEB: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_EXEC); default: ; endcase
        8'h42: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_PCI); default: ; endcase
        8'hC2, 8'hE2: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_EXEC); default: ; endcase
        8'h10, 8'h30, 8'h50, 8'h70, 8'h90, 8'hB0, 8'hD0, 8'hF0, 8'h80:
          case (k)
            4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
            4'd2: uprog = mk(U_IO, S_NT, A_BR);
            4'd3: uprog = mk(U_IO, S_BPX, A_NONE);
            default: ;
          endcase
        8'h82: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
                        4'd3: uprog = mk(U_IO, S_NO, A_BRL); default: ; endcase
        8'h4C: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_JMP); default: ; endcase
        8'h5C: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
                        4'd3: uprog = mk(U_OP3, S_NO, A_JML); default: ; endcase
        8'h6C: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_EAAB0);
                        4'd3: uprog = mk(U_PRL, S_NO, A_NONE); 4'd4: uprog = mk(U_PRH, S_NO, A_JMPI); default: ; endcase
        8'h7C: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_EAPBX);
                        4'd3: uprog = mk(U_IO, S_NO, A_NONE); 4'd4: uprog = mk(U_PRL, S_NO, A_NONE);
                        4'd5: uprog = mk(U_PRH, S_NO, A_JMPI); default: ; endcase
        8'hDC: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_EAAB0);
                        4'd3: uprog = mk(U_PRL, S_NO, A_NONE); 4'd4: uprog = mk(U_PRH, S_NO, A_NONE);
                        4'd5: uprog = mk(U_PRB, S_NO, A_JMLI); default: ; endcase
        8'h20: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
                        4'd3: uprog = mk(U_IO, S_NO, A_NONE); 4'd4: uprog = mk(U_PSHH, S_NO, A_NONE);
                        4'd5: uprog = mk(U_PSHL, S_NO, A_JSR); default: ; endcase
        8'h22: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PSHK, S_NO, A_NONE); 4'd4: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd5: uprog = mk(U_OP3, S_NO, A_NONE); 4'd6: uprog = mk(U_PSHH, S_NO, A_NONE);
                        4'd7: uprog = mk(U_PSHL, S_NO, A_JSL); default: ; endcase
        8'hFC: case (k) 4'd1: uprog = mk(U_OP1, S_NO, A_NONE); 4'd2: uprog = mk(U_PSHH, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PSHL, S_NO, A_NONE); 4'd4: uprog = mk(U_OP2, S_NO, A_EAPBX);
                        4'd5: uprog = mk(U_IO, S_NO, A_NONE); 4'd6: uprog = mk(U_PRL, S_NO, A_NONE);
                        4'd7: uprog = mk(U_PRH, S_NO, A_JMPI); default: ; endcase
        8'h60: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PULL, S_NO, A_NONE); 4'd4: uprog = mk(U_PULH, S_NO, A_NONE);
                        4'd5: uprog = mk(U_IO, S_NO, A_RTS); default: ; endcase
        8'h6B: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PULL, S_NO, A_NONE); 4'd4: uprog = mk(U_PULH, S_NO, A_NONE);
                        4'd5: uprog = mk(U_PULB, S_NO, A_RTL); default: ; endcase
        8'h40: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_PULP, S_NO, A_NONE); 4'd4: uprog = mk(U_PULL, S_NO, A_NONE);
                        4'd5: uprog = mk(U_PULH, S_NO, A_RTS); 4'd6: uprog = mk(U_PULB, S_EMU, A_PBR); default: ; endcase
        8'h54, 8'h44: // MVN, MVP
          case (k)
            4'd1: uprog = mk(U_OP1, S_NO, A_NONE);
            4'd2: uprog = mk(U_OP2, S_NO, A_NONE);
            4'd3: uprog = mk(U_MVR, S_NO, A_NONE);
            4'd4: uprog = mk(U_MVW, S_NO, A_NONE);
            4'd5: uprog = mk(U_IO, S_NO, A_NONE);
            4'd6: uprog = mk(U_IO, S_NO, A_MV);
            default: ;
          endcase
        8'hCB: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_WAIT, S_NO, A_NONE); default: ; endcase
        8'hDB: case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_NONE); 4'd2: uprog = mk(U_IO, S_NO, A_NONE);
                        4'd3: uprog = mk(U_STOP, S_NO, A_NONE); default: ; endcase
        default: // one-cycle implied operations (transfers, flags, INC/DEC/shift A, INX..., XCE, NOP)
          case (k) 4'd1: uprog = mk(U_IOPC, S_NO, A_EXEC); default: ; endcase
      endcase
    end
  endfunction

  // ------------------------------------------------------------------ ALU
  // add with carry (sub: b already inverted), 65816 decimal algorithm; returns {C, V, result}
  function automatic logic [17:0] addc(input logic [15:0] a, input logic [15:0] b, input logic ci,
                                       input logic dec, input logic sub, input logic w);
    logic [19:0] r;
    logic        t7, t15;
    logic        c, v;
    logic [15:0] res;
    if (!dec) begin
      r = {4'd0, a} + {4'd0, b} + {19'd0, ci};
      res = r[15:0];
      c = w ? r[16] : r[8];
      v = w ? (~(a[15] ^ b[15]) & (a[15] ^ r[15])) : (~(a[7] ^ b[7]) & (a[7] ^ r[7]));
    end else begin
      // nibble 0
      r = {16'd0, a[3:0]} + {16'd0, b[3:0]} + {19'd0, ci};
      if (sub) begin c = (r > 20'h0000F); if (!c) r = r - 20'h6; end
      else     begin if (r > 20'h00009) r = r + 20'h6; c = (r > 20'h0000F); end
      // nibble 1
      r = {12'd0, a[7:4], 4'd0} + {12'd0, b[7:4], 4'd0} + {15'd0, c, 4'd0} + {16'd0, r[3:0]};
      t7 = r[7]; t15 = 1'b0;
      if (w) begin
        if (sub) begin c = (r > 20'h000FF); if (!c) r = r - 20'h60; end
        else     begin if (r > 20'h0009F) r = r + 20'h60; c = (r > 20'h000FF); end
        // nibble 2
        r = {8'd0, a[11:8], 8'd0} + {8'd0, b[11:8], 8'd0} + {11'd0, c, 8'd0} + {12'd0, r[7:0]};
        if (sub) begin c = (r > 20'h00FFF); if (!c) r = r - 20'h600; end
        else     begin if (r > 20'h009FF) r = r + 20'h600; c = (r > 20'h00FFF); end
        // nibble 3
        r = {4'd0, a[15:12], 12'd0} + {4'd0, b[15:12], 12'd0} + {7'd0, c, 12'd0} + {8'd0, r[11:0]};
        t15 = r[15];
        v = ~(a[15] ^ b[15]) & (a[15] ^ t15);
        if (sub) begin c = (r > 20'h0FFFF); if (!c) r = r - 20'h6000; end
        else     begin if (r > 20'h09FFF) r = r + 20'h6000; c = (r > 20'h0FFFF); end
      end else begin
        v = ~(a[7] ^ b[7]) & (a[7] ^ t7);
        if (sub) begin c = (r > 20'h000FF); if (!c) r = r - 20'h60; end
        else     begin if (r > 20'h0009F) r = r + 20'h60; c = (r > 20'h000FF); end
      end
      res = r[15:0];
    end
    addc = {c, v, res};
  endfunction

  // read-type operation: returns {dst(0 none,1 C,2 X,3 Y), value16, P}
  function automatic logic [25:0] alu_rd(input logic [4:0] o, input logic [15:0] v, input logic w,
                                         input logic [15:0] c_, input logic [15:0] x_, input logic [15:0] y_,
                                         input logic [7:0] p_);
    logic [15:0] m, t, res;
    logic [17:0] ar;
    logic [16:0] d;
    logic [1:0]  dst;
    logic [7:0]  pp;
    m = w ? 16'hFFFF : 16'h00FF;
    pp = p_; dst = 2'd0; res = 16'd0; t = 16'd0;
    case (o)
      O_LDA: begin t = v & m; dst = 2'd1; res = w ? v : {c_[15:8], v[7:0]}; end
      O_LDX: begin t = v & m; dst = 2'd2; res = v & m; end
      O_LDY: begin t = v & m; dst = 2'd3; res = v & m; end
      O_ORA: begin t = (c_ | v) & m; dst = 2'd1; res = w ? t : {c_[15:8], t[7:0]}; end
      O_AND: begin t = (c_ & v) & m; dst = 2'd1; res = w ? t : {c_[15:8], t[7:0]}; end
      O_EOR: begin t = (c_ ^ v) & m; dst = 2'd1; res = w ? t : {c_[15:8], t[7:0]}; end
      O_ADC, O_SBC: begin
        ar = addc(c_ & m, (o == O_SBC) ? (~v & m) : (v & m), p_[0], p_[3], o == O_SBC, w);
        t = ar[15:0] & m; dst = 2'd1; res = w ? t : {c_[15:8], t[7:0]};
        pp[0] = ar[17]; pp[6] = ar[16];
      end
      O_CMP, O_CPX, O_CPY: begin
        d = {1'b0, ((o == O_CMP) ? c_ : (o == O_CPX) ? x_ : y_) & m} - {1'b0, v & m};
        t = d[15:0] & m;
        pp[0] = !d[16];
      end
      O_BIT: begin
        t = c_ & v & m;
        pp[7] = w ? v[15] : v[7];
        pp[6] = w ? v[14] : v[6];
      end
      default: t = c_ & v & m;   // O_BITI
    endcase
    pp[1] = (t == 16'd0);
    if (o != O_BIT && o != O_BITI) pp[7] = w ? t[15] : t[7];
    alu_rd = {dst, res, pp};
  endfunction

  // read-modify-write operation: returns {value16, P}
  function automatic logic [23:0] alu_rmw(input logic [4:0] o, input logic [15:0] v, input logic w,
                                          input logic [15:0] acc, input logic [7:0] p_);
    logic [15:0] r, m;
    logic [7:0]  pp;
    m = w ? 16'hFFFF : 16'h00FF;
    pp = p_;
    case (o)
      O_ASL: begin r = (v << 1) & m; pp[0] = w ? v[15] : v[7]; end
      O_ROL: begin r = ((v << 1) | {15'd0, p_[0]}) & m; pp[0] = w ? v[15] : v[7]; end
      O_LSR: begin r = (v & m) >> 1; pp[0] = v[0]; end
      O_ROR: begin r = ((v & m) >> 1) | (p_[0] ? (w ? 16'h8000 : 16'h0080) : 16'h0000); pp[0] = v[0]; end
      O_INC: r = (v + 16'd1) & m;
      O_DEC: r = (v - 16'd1) & m;
      O_TSB: r = (v | acc) & m;
      default: r = (v & ~acc) & m;   // O_TRB
    endcase
    if (o == O_TSB || o == O_TRB) pp[1] = ((acc & v & m) == 16'd0);
    else begin pp[1] = (r == 16'd0); pp[7] = w ? r[15] : r[7]; end
    alu_rmw = {r, pp};
  endfunction

  // P with the emulation-mode constraints applied (M = X = 1)
  function automatic logic [7:0] pfix(input logic [7:0] p_, input logic e_);
    pfix = e_ ? (p_ | 8'h30) : p_;
  endfunction

  // EA + 1 with the wrap of the running addressing mode
  function automatic logic [23:0] einc(input logic [23:0] a, input logic [1:0] wm);
    case (wm)
      W24:     einc = a + 24'd1;
      W16:     einc = {a[23:16], a[15:0] + 16'd1};
      default: einc = {a[23:8], a[7:0] + 8'd1};
    endcase
  endfunction

  logic branch_taken;
  always_comb begin
    case (IR[7:6])
      2'd0: branch_taken = (P[7] == IR[5]);
      2'd1: branch_taken = (P[6] == IR[5]);
      2'd2: branch_taken = (P[0] == IR[5]);
      default: branch_taken = (P[1] == IR[5]);
    endcase
    if (IR == 8'h80) branch_taken = 1'b1;
  end

  // ------------------------------------------------------------------ current micro-op (skips resolved)
  /* verilator lint_off UNUSED */
  logic [14:0] u0;          // the running micro-op (its skip condition was resolved a cycle earlier)
  logic [14:0] u1;          // the next micro-op: only its skip condition is used
  /* verilator lint_on UNUSED */
  logic [5:0]  uk;
  logic [4:0]  ua;
  logic        dl0;
  assign dl0 = (D[7:0] == 8'h00);

  function automatic logic skipf(input logic [3:0] s, input logic w16_, input logic dl0_, input logic xf_,
                                 input logic cx_, input logic bt, input logic e_);
    case (s)
      S_W8:  skipf = !w16_;
      S_DL0: skipf = dl0_;
      S_IDX: skipf = xf_ && !cx_;
      S_NT:  skipf = !bt;
      S_BPX: skipf = !(bt && e_ && cx_);
      S_EMU: skipf = e_;
      default: skipf = 1'b0;
    endcase
  endfunction

  // The skip condition of the next micro-op is resolved one cycle early (with the index / branch carry this cycle
  // produces), so the running micro-op is a plain table lookup. A skipped micro-op is never followed by another
  // skippable one, except after a branch not taken, which ends the instruction (step 15 is END in every program).
  always_comb begin
    u0 = uprog(IR, K, INTR, am, kd);
    u1 = uprog(IR, K + 4'd1, INTR, am, kd);
    uk = u0[5:0];
    ua = u0[14:10];
  end


  // ------------------------------------------------------------------ cycle
  logic [15:0] nC, nX, nY, nS, nD, nPC, nOPR, nDAT, nSP;
  logic [7:0]  nDBR, nPBR, nP, nIR, nBNK;
  logic        nE, nINTR, nCX;
  logic [2:0]  nIK;
  logic [23:0] nEA, nIAD;
  logic [1:0]  nEAW;
  logic [3:0]  nK;
  logic        fetch, nmi_take;

  logic [23:0] ab;
  logic        rw, vda, vpa, vpb, mlb;
  logic [7:0]  dout;



  logic [23:0] ea1, ea2;
  assign ea1 = einc(EA, EAW);
  assign ea2 = einc(ea1, EAW);

  logic [15:0] xmask;
  assign xmask = Xf ? 16'h00FF : 16'hFFFF;

  // shared adders: one for every effective address, one for PC, one for the stack pointer, one per index
  // register, one read-modify-write unit
  logic [23:0] ea_base, ea_sum;
  logic [15:0] ea_add, pc_bas, pc_add, pc_sum, sp_bas, sp_sum, s_pull, xs, ys;
  logic        pull;
  logic [4:0]  rmw_op;
  logic [15:0] rmw_v;
  logic        rmw_w;
  logic [23:0] rmw_r;
  always_comb begin
    ea_base = {DBR, DI, OPR[7:0]}; ea_add = 16'd0;
    case (ua)
      A_EADP:  begin ea_base = {8'h00, D}; ea_add = {8'h00, DI}; end
      A_EADPX: begin ea_base = EA; ea_add = X; end
      A_EADPY: begin ea_base = EA; ea_add = Y; end
      A_EASR:  begin ea_base = {8'h00, S}; ea_add = {8'h00, DI}; end
      A_EAABX: ea_add = X;
      A_EAABY: ea_add = Y;
      A_EALNG: ea_base = {DI, OPR};
      A_EALNX: begin ea_base = {DI, OPR}; ea_add = X; end
      A_EAPTR: ea_base = {DBR, DI, DAT[7:0]};
      A_EAPTY: begin ea_base = {DBR, DI, DAT[7:0]}; ea_add = Y; end
      A_EAPTL: ea_base = {DI, DAT};
      A_EAPLY: begin ea_base = {DI, DAT}; ea_add = Y; end
      A_EAAB0: ea_base = {8'h00, DI, OPR[7:0]};
      A_EAPBX: begin ea_base = {PBR, DI, OPR[7:0]}; ea_add = X; end
      default: ;
    endcase
    ea_sum = ea_base + {8'h00, ea_add};

    pc_bas = PC; pc_add = 16'd1;
    case (ua)
      A_BR:         pc_add = {{8{OPR[7]}}, OPR[7:0]};
      A_BRL, A_PER: pc_add = OPR;
      A_MV:         pc_add = 16'hFFFD;
      A_RTS, A_RTL: pc_bas = DAT;
      default: ;
    endcase
    if ((uk == U_PSHH || uk == U_PSHL) && (IR == 8'h20 || IR == 8'h22)) pc_add = 16'hFFFF;   // JSR / JSL push PC-1
    pc_sum = pc_bas + pc_add;

    // stack: "old" instructions stay in page 1 in emulation, "new" ones use the 16-bit S
    pull = (uk == U_PULL || uk == U_PULH || uk == U_PULB || uk == U_PULP);
    sp_bas = (Ef && !newstk) ? {8'h01, S[7:0]} : SP;
    sp_sum = sp_bas + (pull ? 16'h0001 : 16'hFFFF);
    s_pull = (Ef && !newstk) ? {8'h01, sp_sum[7:0]} : sp_sum;

    xs = X + ((IR == 8'h44 || IR == 8'hCA) ? 16'hFFFF : 16'h0001);   // MVP / DEX count down
    ys = Y + ((IR == 8'h44 || IR == 8'h88) ? 16'hFFFF : 16'h0001);   // MVP / DEY count down

    if (uk == U_MOD) begin rmw_op = op; rmw_v = DAT; rmw_w = w16; end
    else begin
      rmw_v = C; rmw_w = !Mf;
      case (IR)
        8'h1A:   rmw_op = O_INC;
        8'h3A:   rmw_op = O_DEC;
        8'h0A:   rmw_op = O_ASL;
        8'h2A:   rmw_op = O_ROL;
        8'h4A:   rmw_op = O_LSR;
        default: rmw_op = O_ROR;
      endcase
    end
    rmw_r = alu_rmw(rmw_op, rmw_v, rmw_w, C, P);
  end

  // push source
  logic [15:0] psrc;
  always_comb begin
    case (IR)
      8'h48: psrc = C;
      8'hDA: psrc = X;
      8'h5A: psrc = Y;
      8'h0B: psrc = D;
      8'hF4, 8'hD4, 8'h62: psrc = DAT;
      8'h20, 8'h22: psrc = pc_sum;   // PC - 1
      default: psrc = PC;   // JSR (a,x), BRK, COP, interrupts
    endcase
  end

  always_comb begin : cyc
    logic [25:0] ar;
    logic [15:0] t16, v16, src;
    logic [7:0]  t8;
    logic        e_dpw;
    logic        do_ex;

    nC = C; nX = X; nY = Y; nS = S; nD = D; nPC = PC; nDBR = DBR; nPBR = PBR; nP = P; nE = Ef;
    nIR = IR; nBNK = BNK; nOPR = OPR; nDAT = DAT; nSP = SP; nINTR = INTR; nIK = IK; nCX = CX;
    nEA = EA; nIAD = IAD; nEAW = EAW; nK = K + 4'd1;
    ab = LA; rw = 1'b1; vda = 1'b0; vpa = 1'b0; vpb = 1'b0; mlb = 1'b0; dout = 8'h00;
    fetch = 1'b0; nmi_take = 1'b0;
    ar = 26'd0; t16 = 16'd0; v16 = 16'd0; src = 16'd0; t8 = 8'd0; do_ex = 1'b0;
    e_dpw = Ef && dl0;

    case (uk)
      U_END: begin
        fetch = 1'b1;
        ab = {PBR, PC}; vda = 1'b1; vpa = 1'b1;
        nK = 4'd1; nSP = S; nCX = 1'b0;
        if (res_pend) begin
          nIR = 8'h00; nINTR = 1'b1; nIK = I_RES;
        end else if (abt_pend || nmi_pend || (!IRQ_n && !P[2])) begin
          nIR = 8'h00; nINTR = 1'b1;
          nIK = abt_pend ? I_ABT : nmi_pend ? I_NMI : I_IRQ;
          nmi_take = !abt_pend && nmi_pend;
          if (abt_pend) begin
            nC = aC; nX = aX; nY = aY; nS = aS; nSP = aS; nD = aD; nPC = aPC; nDBR = aDBR; nPBR = aPBR;
            nP = aP; nE = aE;
          end
        end else begin
          nIR = DI; nINTR = 1'b0;
          nPC = pc_sum;
        end
      end
      U_OP1, U_IMM1: begin
        ab = {PBR, PC}; vpa = 1'b1; nPC = pc_sum;
        nOPR[7:0] = DI; nDAT[7:0] = DI;
        if (uk == U_IMM1 && !w16) do_ex = 1'b1;
      end
      U_OP2, U_IMM2: begin
        ab = {PBR, PC}; vpa = 1'b1; nPC = pc_sum;
        nOPR[15:8] = DI; nDAT[15:8] = DI;
        if (uk == U_IMM2) do_ex = 1'b1;
      end
      U_OP3: begin
        ab = {PBR, PC}; vpa = 1'b1; nPC = pc_sum; nBNK = DI;
      end
      U_IOPC: ab = {PBR, PC};
      U_IO: ab = LA;
      U_IOX: ab = IAD;
      U_DRL: begin ab = EA;  vda = 1'b1; nDAT[7:0] = DI; if (!w16) do_ex = 1'b1; end
      U_DRH: begin ab = ea1; vda = 1'b1; nDAT[15:8] = DI; do_ex = 1'b1; end
      U_DWL, U_DWH: begin
        ab = (uk == U_DWL) ? EA : ea1; vda = 1'b1; rw = 1'b0;
        case (op)
          O_STA: src = C;
          O_STX: src = X;
          O_STY: src = Y;
          default: src = 16'd0;
        endcase
        dout = (uk == U_DWL) ? src[7:0] : src[15:8];
      end
      U_MRL: begin ab = EA;  vda = 1'b1; mlb = 1'b1; nDAT[7:0] = DI; end
      U_MRH: begin ab = ea1; vda = 1'b1; mlb = 1'b1; nDAT[15:8] = DI; end
      U_MOD: begin
        ab = LA; mlb = 1'b1;
        if (Ef) begin rw = 1'b0; dout = DAT[7:0]; end
        nDAT = rmw_r[23:8]; nP = rmw_r[7:0];
      end
      U_MWH: begin ab = ea1; vda = 1'b1; mlb = 1'b1; rw = 1'b0; dout = DAT[15:8]; end
      U_MWL: begin ab = EA;  vda = 1'b1; mlb = 1'b1; rw = 1'b0; dout = DAT[7:0]; end
      U_PRL: begin ab = EA;  vda = 1'b1; nDAT[7:0] = DI; end
      U_PRH: begin ab = ea1; vda = 1'b1; nDAT[15:8] = DI; end
      U_PRB: begin ab = ea2; vda = 1'b1; nBNK = DI; end
      U_PSHH, U_PSHL, U_PSHK, U_PSHB, U_PSHP: begin
        ab = {8'h00, sp_bas}; vda = 1'b1; rw = 1'b0;
        case (uk)
          U_PSHH: dout = psrc[15:8];
          U_PSHL: dout = psrc[7:0];
          U_PSHK: dout = PBR;
          U_PSHB: dout = DBR;
          default: dout = (INTR && IK != I_RES) ? (pfix(P, Ef) & ~(Ef ? 8'h10 : 8'h00)) : pfix(P, Ef);
        endcase
        if (INTR && IK == I_RES) begin rw = 1'b1; dout = 8'h00; end   // reset: the pushes are reads
        nSP = (Ef && !newstk) ? {8'h01, sp_sum[7:0]} : sp_sum;
        nS = Ef ? {8'h01, sp_sum[7:0]} : sp_sum;
      end
      U_PULL, U_PULH, U_PULB, U_PULP: begin
        ab = {8'h00, s_pull}; vda = 1'b1;
        nSP = s_pull;
        nS = Ef ? {8'h01, s_pull[7:0]} : s_pull;
        case (uk)
          U_PULL: nDAT[7:0] = DI;
          U_PULH: nDAT[15:8] = DI;
          U_PULB: nBNK = DI;
          default: nP = pfix(DI, Ef);
        endcase
        // stack loads execute on their last byte
        if ((uk == U_PULL && !w16) || uk == U_PULH) begin
          v16 = (uk == U_PULH) ? {DI, DAT[7:0]} : {8'h00, DI};
          case (IR)
            8'h68: begin
              nC = w16 ? v16 : {C[15:8], v16[7:0]};
              nP[1] = w16 ? (v16 == 16'd0) : (v16[7:0] == 8'd0); nP[7] = w16 ? v16[15] : v16[7];
            end
            8'hFA, 8'h7A: begin
              if (IR == 8'hFA) nX = v16; else nY = v16;
              nP[1] = (v16 == 16'd0); nP[7] = w16 ? v16[15] : v16[7];
            end
            8'h2B: begin nD = v16; nP[1] = (v16 == 16'd0); nP[7] = v16[15]; end
            8'hAB: begin nDBR = v16[7:0]; nP[1] = (v16[7:0] == 8'd0); nP[7] = v16[7]; end
            default: ;
          endcase
        end
        if (uk == U_PULP) begin
          if (nP[4]) begin nX[15:8] = 8'h00; nY[15:8] = 8'h00; end
        end
      end
      U_VECL, U_VECH: begin
        vda = 1'b1; vpb = 1'b1;
        if (INTR) begin
          case (IK)
            I_RES:   t8 = 8'hFC;
            I_ABT:   t8 = Ef ? 8'hF8 : 8'hE8;
            I_NMI:   t8 = Ef ? 8'hFA : 8'hEA;
            default: t8 = Ef ? 8'hFE : 8'hEE;
          endcase
        end else if (IR == 8'h02) t8 = Ef ? 8'hF4 : 8'hE4;
        else t8 = Ef ? 8'hFE : 8'hE6;
        ab = {16'h00FF, t8 | {7'd0, uk == U_VECH}};
        if (uk == U_VECL) nDAT[7:0] = DI;
      end
      U_MVR: begin ab = {OPR[15:8], X}; vda = 1'b1; nDAT[7:0] = DI; end
      U_MVW: begin ab = {OPR[7:0], Y}; vda = 1'b1; rw = 1'b0; dout = DAT[7:0]; end
      U_WAIT: begin
        ab = LA;
        nK = K;
        if (nmi_pend || !IRQ_n || abt_pend) nK = K + 4'd1;
      end
      U_STOP: begin ab = LA; nK = K; end
      default: ;
    endcase

    // execute a read-type data operation on its last operand byte
    if (do_ex) begin
      v16 = (uk == U_DRH || uk == U_IMM2) ? {DI, DAT[7:0]} : {8'h00, DI};
      ar = alu_rd(op, v16, w16, C, X, Y, P);
      case (ar[25:24])
        2'd1: nC = ar[23:8];
        2'd2: nX = ar[23:8];
        2'd3: nY = ar[23:8];
        default: ;
      endcase
      nP = ar[7:0];
    end

    // end-of-cycle actions
    case (ua)
      A_EADP: begin
        nEA = {8'h00, ea_sum[15:0]};
        // emulation, DL = 0: the direct page wraps within its page (not for [d], [d],y, PEI)
        nEAW = (e_dpw && !(am == AM_DPIL || am == AM_DPILY || IR == 8'hD4)) ? W8 : W16;
      end
      A_EADPX, A_EADPY: nEA = e_dpw ? {EA[23:8], ea_sum[7:0]} : {8'h00, ea_sum[15:0]};
      A_EASR: begin nEA = {8'h00, ea_sum[15:0]}; nEAW = W16; end
      A_EAABX, A_EAABY, A_EAPTY: begin
        nEA = ea_sum; nEAW = W24;
        nIAD = {ea_base[23:8], ea_sum[7:0]}; nCX = ea_sum[8] ^ ea_base[8] ^ ea_add[8];
      end
      A_EAABS, A_EALNG, A_EALNX, A_EAPTR, A_EAPTL, A_EAPLY: begin nEA = ea_sum; nEAW = W24; end
      A_EAAB0: begin nEA = ea_sum; nEAW = W16; end
      A_EAPBX: begin nEA = {PBR, ea_sum[15:0]}; nEAW = W16; end
      A_JMP:  nPC = {DI, OPR[7:0]};
      A_JML:  begin nPC = OPR; nPBR = DI; end
      A_JMPI: nPC = {DI, DAT[7:0]};
      A_JMLI: begin nPC = DAT; nPBR = DI; end
      A_JSR:  nPC = OPR;
      A_JSL:  begin nPC = OPR; nPBR = BNK; end
      A_RTS:  nPC = (IR == 8'h40) ? {DI, DAT[7:0]} : pc_sum;
      A_RTL:  begin nPC = pc_sum; nPBR = DI; end
      A_PBR:  nPBR = DI;
      A_BR: begin
        nCX = (pc_sum[15:8] != PC[15:8]);
        nPC = pc_sum;
      end
      A_BRL: nPC = pc_sum;
      A_PER: nDAT = pc_sum;
      A_PCI: nPC = pc_sum;
      A_VEC: begin
        nPC = {DI, DAT[7:0]}; nPBR = 8'h00;
        nP[2] = 1'b1; nP[3] = 1'b0;
        nINTR = 1'b0;
      end
      A_MV: begin
        nX = xs & xmask; nY = ys & xmask;
        nC = C - 16'd1;
        nDBR = OPR[7:0];
        if (C != 16'h0000) nPC = pc_sum;   // PC - 3: repeat
      end
      A_EXEC: begin
        case (IR)
          8'h18: nP[0] = 1'b0;
          8'h38: nP[0] = 1'b1;
          8'h58: nP[2] = 1'b0;
          8'h78: nP[2] = 1'b1;
          8'hB8: nP[6] = 1'b0;
          8'hD8: nP[3] = 1'b0;
          8'hF8: nP[3] = 1'b1;
          8'hC2: nP = pfix(P & ~OPR[7:0], Ef);
          8'hE2: begin nP = P | OPR[7:0]; if (OPR[4]) begin nX[15:8] = 8'h00; nY[15:8] = 8'h00; end end
          8'hFB: begin
            nE = P[0]; nP[0] = Ef;
            if (P[0]) begin nP[5:4] = 2'b11; nX[15:8] = 8'h00; nY[15:8] = 8'h00; nS[15:8] = 8'h01; end
          end
          8'hEB: begin
            nC = {C[7:0], C[15:8]};
            nP[1] = (C[15:8] == 8'd0); nP[7] = C[15];
          end
          8'h9A: nS = Ef ? {8'h01, X[7:0]} : X;
          8'h1B: nS = Ef ? {8'h01, C[7:0]} : C;
          8'h5B: begin nD = C; nP[1] = (C == 16'd0); nP[7] = C[15]; end
          8'h7B: begin nC = D; nP[1] = (D == 16'd0); nP[7] = D[15]; end
          8'h3B: begin nC = S; nP[1] = (S == 16'd0); nP[7] = S[15]; end
          8'hEA: ;
          8'hAA, 8'hA8, 8'hBA, 8'h9B, 8'hBB, 8'hE8, 8'hC8, 8'hCA, 8'h88: begin
            // results in an index register (X width)
            case (IR)
              8'hAA, 8'hA8: t16 = C;
              8'hBA:        t16 = S;
              8'h9B:        t16 = X;
              8'hBB:        t16 = Y;
              8'hE8, 8'hCA: t16 = xs;
              default:      t16 = ys;
            endcase
            t16 = t16 & xmask;
            if (IR == 8'hAA || IR == 8'hBA || IR == 8'hE8 || IR == 8'hCA || IR == 8'hBB) nX = t16; else nY = t16;
            nP[1] = (t16 == 16'd0); nP[7] = Xf ? t16[7] : t16[15];
          end
          8'h8A, 8'h98: begin
            t16 = (IR == 8'h8A) ? X : Y;
            if (Mf) begin nC[7:0] = t16[7:0]; nP[1] = (t16[7:0] == 8'd0); nP[7] = t16[7]; end
            else    begin nC = t16; nP[1] = (t16 == 16'd0); nP[7] = t16[15]; end
          end
          default: begin
            // accumulator read-modify-write: INC A, DEC A, ASL A, ROL A, LSR A, ROR A
            nC = Mf ? {C[15:8], rmw_r[15:8]} : rmw_r[23:8];
            nP = rmw_r[7:0];
          end
        endcase
      end
      default: ;
    endcase

    // next micro-op skipped?
    if (uk != U_END && uk != U_WAIT && uk != U_STOP && u1[5:0] != U_END &&
        skipf(u1[9:6], w16, dl0, Xf, nCX, branch_taken, Ef))
      nK = (u1[9:6] == S_NT) ? 4'd15 : K + 4'd2;
  end

  // pins: M / X / E as at the start of the instruction (the opcode fetch already shows the new values)
  assign A = ab; assign R_W_n = rw; assign VDA = vda; assign VPA = vpa; assign VP_n = !vpb; assign ML_n = !mlb;
  assign DO = dout;
  assign Sync = vda & vpa;
  assign E  = fetch ? Ef : sE;
  assign MF = fetch ? Mf : sM;
  assign XF = fetch ? Xf : sX;
  assign Wait_n = (uk != U_WAIT);
  assign NMI_ack = nmi_take & Enable & Rdy;

  always_ff @(posedge Clk or negedge Res_n) begin
    if (!Res_n) begin
      IR <= 8'h00; K <= 4'd0; INTR <= 1'b1; IK <= I_RES; res_pend <= 1'b1;
      Ef <= 1'b1; P <= 8'h34; D <= 16'h0000; DBR <= 8'h00; PBR <= 8'h00;
      S <= 16'h01FF; X <= 16'h0000; Y <= 16'h0000;
      nmi_pend <= 1'b0; nmi_d <= 1'b1; abt_pend <= 1'b0;
      sM <= 1'b1; sX <= 1'b1; sE <= 1'b1;
    end else if (Enable && Rdy) begin
      X <= nX; Y <= nY; S <= nS; D <= nD; DBR <= nDBR; PBR <= nPBR; P <= pfix(nP, nE);
      Ef <= nE; IR <= nIR; K <= nK; INTR <= nINTR; IK <= nIK;
      if (fetch) begin
        sM <= Mf; sX <= Xf; sE <= Ef;
        res_pend <= 1'b0;
        abt_pend <= 1'b0;
      end
      nmi_d <= NMI_n;
      if (nmi_take) nmi_pend <= 1'b0;
      else if (nmi_d && !NMI_n) nmi_pend <= 1'b1;
      if (!Abort_n && !fetch) abt_pend <= 1'b1;
    end
  end

  // registers without reset (they hold while Res_n is low)
  /* verilator lint_off SYNCASYNCNET */
  always_ff @(posedge Clk) begin
    if (Res_n && Enable && Rdy) begin
      C <= nC; PC <= nPC;
      EA <= nEA; IAD <= nIAD; EAW <= nEAW; OPR <= nOPR; DAT <= nDAT; BNK <= nBNK; SP <= nSP; CX <= nCX;
      LA <= ab;
      if (fetch) begin
        aC <= C; aX <= X; aY <= Y; aS <= S; aD <= D; aPC <= PC; aDBR <= DBR; aPBR <= PBR; aP <= P; aE <= Ef;
      end
    end
  end
  /* verilator lint_on SYNCASYNCNET */
endmodule

// t65sv_T65: drop-in replacement for the T65 entity (same ports, DEBUG record packed {I,A,X,Y,S,P}).
// Mode 2'b00 = NMOS 6502 identical to T65 Ver 315; 2'b01/2'b10/2'b11 = 65C02 of flavour C02.
// C816 = 1: the core is a W65C816S whatever Mode is (T65's own Mode "10" is a partial 65816 that is not
// reproduced; a run-time 6502/65816 switch would cost both engines' area).
// Derived from T65 by Daniel Wallner; MikeJ, WoS, SzGy and contributors (MiSTer-devel lineage); licence: see t65sv.sv.
module t65sv_T65 #(
  parameter int C02        = 1,     // 65C02 flavour for Mode != 00: 1 WDC, 2 Rockwell, 3 65SC02, 0 none
  parameter bit NO_DECIMAL = 1'b0,
  parameter bit C02_FIXED  = 1'b0,  // 1: always the 65C02 (Mode ignored)
  parameter bit C816       = 1'b0   // 1: always the 65C816 (Mode, SO_n, BCD_en ignored)
) (
  input  logic [1:0]  Mode,
  input  logic        Res_n,
  input  logic        Enable,
  input  logic        Clk,
  input  logic        Rdy,
  input  logic        Abort_n,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  input  logic        SO_n,
  input  tri1         BCD_en,   // optional (upstream C64_MiSTer T65 port); unconnected = decimal enabled
  output logic        R_W_n,
  output logic        Sync,
  output logic        EF,
  output logic        MF,
  output logic        XF,
  output logic        ML_n,
  output logic        VP_n,
  output logic        VDA,
  output logic        VPA,
  output logic [23:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO,
  output logic [63:0] Regs,
  output logic [47:0] DEBUG,
  output logic        NMI_ack
);
  t65sv #(.C02(C02), .NO_DECIMAL(NO_DECIMAL), .C02_FIXED(C02_FIXED), .C816(C816)) u_core (
    .Mode(Mode), .Res_n(Res_n), .Enable(Enable), .Clk(Clk), .Rdy(Rdy), .Abort_n(Abort_n),
    .IRQ_n(IRQ_n), .NMI_n(NMI_n), .SO_n(SO_n), .BCD_en(BCD_en), .R_W_n(R_W_n), .Sync(Sync), .EF(EF), .MF(MF),
    .XF(XF), .ML_n(ML_n), .VP_n(VP_n), .VDA(VDA), .VPA(VPA), .A(A), .DI(DI), .DO(DO),
    .Regs(Regs), .DEBUG(DEBUG), .NMI_ack(NMI_ack));
endmodule

// t65sv variant tops: 6510/8500, 6507, 2A03/2A07, 65C02 (WDC / Rockwell / 65SC02), 65C816.
// Derived from T65 by Daniel Wallner; MikeJ, WoS, SzGy and contributors (MiSTer-devel lineage); licence: see t65sv.sv.

// 6510/8500 on-chip I/O port: $0000 = data direction (1 = output), $0001 = data.
module t65sv_ioport #(
  parameter int PORT_BITS = 6   // pins P0..P(PORT_BITS-1); higher bits have no pin and keep their last driven level
) (
  input  logic       Clk,
  input  logic       Res_n,
  input  logic       Enable,
  input  logic [15:0] A,
  input  logic       R_W_n,
  input  logic [7:0] DO,
  input  logic [7:0] P_I,       // pin levels when configured as input
  output logic       Sel,       // CPU is addressing $0000/$0001
  output logic [7:0] Rd,        // value the CPU reads at $0000/$0001
  output logic [7:0] P_O,       // data register
  output logic [7:0] P_DDR      // data direction register
);
  logic [7:0] ddr, data, held, pins;

  assign Sel   = (A[15:1] == 15'd0);
  assign P_O   = data;
  assign P_DDR = ddr;

  always_comb begin
    pins = P_I;
    if (PORT_BITS < 8) pins = (P_I & ((8'h01 << PORT_BITS) - 8'h01)) | (held & ~((8'h01 << PORT_BITS) - 8'h01));
  end

  assign Rd = A[0] ? ((data & ddr) | (pins & ~ddr)) : ddr;

  always_ff @(posedge Clk or negedge Res_n) begin
    if (!Res_n) begin
      ddr  <= 8'h00;
      data <= 8'h00;
      held <= 8'h00;
    end else begin
      held <= (data & ddr) | (held & ~ddr);
      if (Enable && Sel && !R_W_n) begin
        if (A[0]) data <= DO;
        else      ddr  <= DO;
      end
    end
  end
endmodule

// MOS 6510 / 8500: NMOS core (identical to T65 Mode "00") plus the I/O port.
// The external bus still sees $0000/$0001 accesses (as on the real chip); reads there return the port.
// AEC only tells the system when the CPU drives the bus (the core itself is stopped with RDY).
module t65sv_6510 #(
  parameter int PORT_BITS = 6
) (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  input  logic        AEC,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  output logic        R_W_n,
  output logic        Sync,
  output logic        Bus_En,   // = AEC: address, data and R/W are valid on the external bus
  output logic [15:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO,
  input  logic [7:0]  P_I,
  output logic [7:0]  P_O,
  output logic [7:0]  P_DDR
);
  /* verilator lint_off UNUSED */
  logic [23:0] a24;   // A[23:16] is T65's dummy bank byte
  /* verilator lint_on UNUSED */
  logic [7:0]  di_core, port_rd;
  logic        port_sel;

  assign A      = a24[15:0];
  assign Bus_En = AEC;
  assign di_core = !R_W_n ? DO : port_sel ? port_rd : DI;

  t65sv #(.C02(0)) u_core (
    .Mode(2'b00), .Res_n(Res_n), .Enable(Enable), .Clk(Clk), .Rdy(Rdy), .Abort_n(1'b1),
    .IRQ_n(IRQ_n), .NMI_n(NMI_n), .SO_n(1'b1), .BCD_en(1'b1), .R_W_n(R_W_n), .Sync(Sync),
    .EF(), .MF(), .XF(), .ML_n(), .VP_n(), .VDA(), .VPA(),
    .A(a24), .DI(di_core), .DO(DO), .Regs(), .DEBUG(), .NMI_ack());

  t65sv_ioport #(.PORT_BITS(PORT_BITS)) u_port (
    .Clk(Clk), .Res_n(Res_n), .Enable(Enable), .A(a24[15:0]), .R_W_n(R_W_n), .DO(DO),
    .P_I(P_I), .Sel(port_sel), .Rd(port_rd), .P_O(P_O), .P_DDR(P_DDR));
endmodule

// MOS 6507: 13 address lines, no IRQ/NMI/SO pins.
module t65sv_6507 (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  output logic        R_W_n,
  output logic [12:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO
);
  /* verilator lint_off UNUSED */
  logic [23:0] a24;   // A[23:16] is T65's dummy bank byte
  /* verilator lint_on UNUSED */
  assign A = a24[12:0];
  t65sv #(.C02(0)) u_core (
    .Mode(2'b00), .Res_n(Res_n), .Enable(Enable), .Clk(Clk), .Rdy(Rdy), .Abort_n(1'b1),
    .IRQ_n(1'b1), .NMI_n(1'b1), .SO_n(1'b1), .BCD_en(1'b1), .R_W_n(R_W_n), .Sync(),
    .EF(), .MF(), .XF(), .ML_n(), .VP_n(), .VDA(), .VPA(),
    .A(a24), .DI(DI), .DO(DO), .Regs(), .DEBUG(), .NMI_ack());
endmodule

// Ricoh 2A03 / 2A07 CPU part: NMOS core, D flag settable but ADC/SBC/ARR always binary.
module t65sv_2A03 (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  output logic        R_W_n,
  output logic        Sync,
  output logic [15:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO
);
  /* verilator lint_off UNUSED */
  logic [23:0] a24;   // A[23:16] is T65's dummy bank byte
  /* verilator lint_on UNUSED */
  assign A = a24[15:0];
  t65sv #(.C02(0), .NO_DECIMAL(1'b1)) u_core (
    .Mode(2'b00), .Res_n(Res_n), .Enable(Enable), .Clk(Clk), .Rdy(Rdy), .Abort_n(1'b1),
    .IRQ_n(IRQ_n), .NMI_n(NMI_n), .SO_n(1'b1), .BCD_en(1'b1), .R_W_n(R_W_n), .Sync(Sync),
    .EF(), .MF(), .XF(), .ML_n(), .VP_n(), .VDA(), .VPA(),
    .A(a24), .DI(DI), .DO(DO), .Regs(), .DEBUG(), .NMI_ack());
endmodule

// 65C02: FLAVOUR 1 = WDC W65C02S (RMB/SMB/BBR/BBS, WAI/STP), 2 = Rockwell R65C02 (bit ops),
// 3 = Synertek/GTE 65SC02 (neither).
module t65sv_65C02 #(
  parameter int FLAVOUR = 1
) (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  input  logic        SO_n,
  output logic        R_W_n,
  output logic        Sync,
  output logic        VP_n,
  output logic        ML_n,
  output logic [15:0] A,
  input  logic [7:0]  DI,
  output logic [7:0]  DO
);
  /* verilator lint_off UNUSED */
  logic [23:0] a24;   // A[23:16] is T65's dummy bank byte
  /* verilator lint_on UNUSED */
  assign A = a24[15:0];
  t65sv #(.C02(FLAVOUR), .C02_FIXED(1'b1)) u_core (
    .Mode(2'b01), .Res_n(Res_n), .Enable(Enable), .Clk(Clk), .Rdy(Rdy), .Abort_n(1'b1),
    .IRQ_n(IRQ_n), .NMI_n(NMI_n), .SO_n(SO_n), .BCD_en(1'b1), .R_W_n(R_W_n), .Sync(Sync),
    .EF(), .MF(), .XF(), .ML_n(ML_n), .VP_n(VP_n), .VDA(), .VPA(),
    .A(a24), .DI(DI), .DO(DO), .Regs(), .DEBUG(), .NMI_ack());
endmodule

// W65C816S with its own pin names. M and X are separate outputs (the chip multiplexes them on MX with PHI2).
// Wait_n is low while WAI waits (the chip drives its RDY pin low then). Same engine as t65sv #(.C816(1)).
module t65sv_65C816 (
  input  logic        Clk,
  input  logic        Enable,
  input  logic        Res_n,
  input  logic        Rdy,
  input  logic        Abort_n,
  input  logic        IRQ_n,
  input  logic        NMI_n,
  output logic [23:0] A,        // {bank (D7..D0 during PHI2 low on the chip), A15..A0}
  input  logic [7:0]  DI,
  output logic [7:0]  DO,
  output logic        R_W_n,
  output logic        VDA,
  output logic        VPA,
  output logic        VP_n,
  output logic        ML_n,
  output logic        E,
  output logic        MF,
  output logic        XF,
  output logic        Wait_n
);
  t65sv816 u_816 (
    .Clk(Clk), .Enable(Enable), .Res_n(Res_n), .Rdy(Rdy), .Abort_n(Abort_n), .IRQ_n(IRQ_n), .NMI_n(NMI_n),
    .DI(DI), .A(A), .DO(DO), .R_W_n(R_W_n), .VDA(VDA), .VPA(VPA), .VP_n(VP_n), .ML_n(ML_n), .E(E), .MF(MF),
    .XF(XF), .Sync(), .Wait_n(Wait_n), .NMI_ack(), .Regs_PC(), .Regs_C(), .Regs_X(), .Regs_Y(), .Regs_S(),
    .Regs_D(), .Regs_DBR(), .Regs_PBR(), .Regs_P(), .Regs_E(), .Regs_IR());
endmodule
